import{A as e}from"./index-D8uCG-EY.js";const t={adv_g141_shiyi:{id:"adv_g141_shiyi",title:"白发老丈在剑山道替失物寻主人",mother:"M6",channel:"T1",rarity:1,entry:{node:"kw_jianshan",chance:.08},stages:[{xinglu:"是岁剑山道逢白发老丈。白发老丈的话糙，理却直——「东西无主的时候最可怜——可怜它们连个喊它名字的人都没有。」",text:"白发老丈见你打量一船漂来的遗物，主动开了口：「别看它们破——件件都有来处，件件都在等人。」「我这册子记了二十年。」白发老丈翻着一船漂来的遗物边的旧簿，「每件失物什么样子、哪儿捡的、像是谁丢的——都记着。册子比我的脑子靠得住。人的记忆会骗人，字不会。」「客人有闲功夫没有？」白发老丈半开玩笑，「搭把手，帮我给这箱子归归类。你归过的，我记下——算你在这行挂个号。」",options:[{label:"「这故事有意思，讲讲。」",goto:1,effect:void 0},{label:"「谁丢了东西自己不会找。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人？」白发老丈摇头，「你丢了东西就知道了——丢东西的人，个个都是痴人。我见过丢了亡妻一支簪子的铁塔似的汉子，在我这儿哭成泪人。你笑痴——那是你的福气。真到了痴那天，你盼着世上多几个痴人。」他把门为你拉开，「慢走。愿你一辈子用不上我这行。」"}}]},{xinglu:"是岁剑山道一课。白发老丈把话说到根上——「我这一行没有大买卖——都是小东西，可小东西连着大心事。」",text:"「拾遗这行，也有发懵的时候。」白发老丈说，「讲一件，你听听值不值。」「祖师爷是邮差——这话说来话长。」白发老丈笑了，「我师父说的：邮差一辈子送的是信，可信里装的是人的命。丢一封信，散一门亲、误一条命的事都有。所以我师父说，收失物的，跟送信的一个理——你手里过的不是物，是人家的念想。」白发老丈拍了拍一船漂来的遗物，「我守着这屋子念想，二十年，一件没敢怠慢。」白发老丈送你到门口，回身望着满屋一船漂来的遗物：「客人，你笑我守破烂也好，敬我守念想也好——这屋子东西，早晚会一件一件回到人手里。到那时候，我这屋子空了，我这心，也就满了。」",options:[{label:"「您守的不是破烂。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"恩",text:"在剑山道帮白发老丈归类失物，替七户人家拆了死结"},text_after:"你摸着那件失物说了自己的猜测——「丢它的人手上有茧，是做粗活出身，可这物件绣工极细，是替珍视的人做的。」白发老丈怔了半天，说：「二十年，头一回有人把它说活。」他把它单独搁到一个格子里，「照你这么说，它主人家里必还有一个等它的人。我再寻十年，也值得。」"}},{label:"「失物多了，你拾得过来？」",end:!0,effect:{stat:{wuxing:1},text_after:"「再买就是？」白发老丈笑了，「钱能买回来的，都不叫失物。叫失物的，钱买不回来——亡人的东西、旧人的信、娃他娘缝的鞋。这些丢了，买一百件新的，心里那个窟窿还是圆不上。你年纪轻，还没到懂的时候——哪天懂了，别哭，来我这儿坐坐。」"}}]}]},adv_g142_wenlu:{id:"adv_g142_wenlu",title:"在剑炉街，只问不答的独臂客",mother:"M7",channel:"T2",rarity:2,entry:{node:"kw_jianlu",chance:.07},stages:[{xinglu:"是岁剑炉街逢独臂客。独臂客的话糙，理却直——「人这一生，答案会过期——问题不会。」",text:"你路过剑炉街，独臂客拦住你：「客人，问你个事——你答不上来不要紧。」「我这一只装满纸条的竹筒上挂满了问句。」独臂客指给你看，「有客人替我答的，有我自己想了三十年的。挂在这儿——路过的人看一眼，想一会儿，这一会儿，就值。」「我考考你。」独臂客眼睛一亮，「就一个问题——答上来，我这一只装满纸条的竹筒上的问题随你挑一个带走。」",options:[{label:"「我是在奔着一条路。」",goto:1,effect:void 0},{label:"「你到底答不答。」",end:!0,effect:{stat:{wuxing:1},text_after:"「无聊？」独臂客哈哈大笑，「你这话说得对——问题是挺无聊的。答案多痛快，一刀见血。可我告诉你，一刀见血的痛快，跟一刀断命的糊涂，是同一个刀法。你嫌我无聊，就是嫌自己想事太慢——慢工出的东西，急工比不了。走吧走吧，等你哪天急不动了，自然会回来找无聊。」"}}]},{xinglu:"是岁剑炉街一课。独臂客把话说到根上——「问路的人最聪明——他省下的冤枉路，就是他的学问。」",text:"「我最得意的一个问题，」独臂客压低了声音，「救过一个人。」「我师父哑，怎么教我问？」独臂客说，「他用手指比划，写在沙地上。他写的第一个问句是：你今天看见了什么？我答：什么都看见了。他摇头，写：不——你看见的是你觉得的。这句话我琢磨了半辈子。到今天，我每天还问自己这一句。」独臂客指指一只装满纸条的竹筒，「这上头挂的头一个问题，就是他写的。」独臂客把一张纸条郑重推给你：「这个问题归你了。不急——哪天想通了，丢进我这竹筒里就行，人不用来。问题认字不认人。」",options:[{label:"「这问题，我收下了。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"恩",text:"在独臂客店里吵了一架，各自往前挪了半步"},text_after:"「看，还是觉得——这一句你带走了。」独臂客满意地送你出门。后来你在生意上、恩怨里、抉择前，无数次问自己这一句。它不能替你做对的事——可它让你少做了许多自以为对的事。你从此逢人便传这句话，传的时候都说是从一个怪老头那儿听来的。"}},{label:"「故弄玄虚，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「从不问路？」独臂客看着你，忽然认真了，「客人，我不拦你。可我送你一句话：不问路的人，不是路盲——是路盲里胆子最大的。老天爷不在乎你问不问，它只管把你引到岔路口。你凭本事闯，闯对了是命大，闯错了——」他顿了顿，「没有人给你收尸。走吧。这话搁这儿，你哪天想起，算我的。」"}}]}]},adv_g143_jizhang:{id:"adv_g143_jizhang",title:"独臂客在矿石市替人情记着账",mother:"M8",channel:"T3",rarity:2,entry:{node:"kw_kuangshi",chance:.09},stages:[{xinglu:"是岁矿石市逢独臂客。独臂客的话糙，理却直——「一笔账两头记——欠的人记着还，还的人记着情，两头都记着，人就亲了。」",text:"独臂客正往一柜子分门别类的借据上添一笔，添完念给你听：「某年某月，某人还清。」——念得像唱。「有人问我，死人欠的账记来做什么。」独臂客说，「记。儿子长大来翻账——看见他爹当年受过谁的恩、还过谁的债，他就知道自己是个什么根底。账本就是家谱，还是最老实的那一页。」独臂客递给你一盏茶：「先别急着走。听我说说这账本上的头一页——听完你就知道，账不是冰的。」",options:[{label:"「我誊这页。」",goto:1,effect:void 0},{label:"「你这行当，多管闲事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「记它做什么？」独臂客把笔搁下，「你不记，它就不存在了么？不——它在你心里烂着，在他心里烂着，两败俱伤。记出来，才有得还、有得清、有得忘。账不是记仇——是把烂在心里的东西，拿到日头底下晾晾。」"}}]},{xinglu:"是岁矿石市一课。独臂客把话说到根上——「钱账好记，情账难记——难记的才需要人记。」",text:"「我这行也有对头。」独臂客冷笑一声，「有人最恨我这本账——你猜是谁？」「记错的那笔，是早年一个后生替他病重的爹来还账。」独臂客声音哑了，「我记成『还清』，其实差着半吊。他爹咽气前问起，还念叨着那半吊。等我发现，人已经没了，账差了，说不清了。」独臂客翻开账本给我看——那页边上有行小字：「错在我，补录于三年后，按利全还，还账人：他儿子。」——「他儿子在外头挣了三年，回来把半吊连本带利还了，还非要多还一份。我说不该多。他说：我爹没还完的账，我替他记得体面些。从那天起，我每笔记三遍。」「替我记一笔。」独臂客忽然说，「就说：今天有个过路的客人，坐下来听完了整本账。这一笔记下——你也是账里的人了。」",options:[{label:"「把我记上。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"恩",text:"在独臂客账上被记了一笔：「今天有个客人，听完了整本账」"},text_after:"「当得起什么。」独臂客连连摆手，「我这行，说到底是替人管着念想。念想是他们的，我只是个保管员。」可你看得出来，他说这话时腰板挺得笔直——一个一辈子被几千户人信着的人，那份挺直，是拿三十年的笔一笔一笔撑起来的。"}},{label:"「死账就销了罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何苦？」独臂客笑了，「我这一柜账，年年有人来对、来还、来谢——我苦什么？苦的是你们这些不记的：受了恩转脸就忘，欠了债装不知道——你以为你们轻省？你们那才是苦——账在心里烂着，夜夜硌得慌。我睡得着，就凭我这柜子。」"}}]}]},adv_g144_shouwu:{id:"adv_g144_shouwu",title:"铸剑世家工坊来了个守着一件旧物的独臂客",mother:"M5",channel:"T1",rarity:2,entry:{node:"kw_gongfang",chance:.11},stages:[{xinglu:"是岁铸剑世家工坊逢独臂客。独臂客的话糙，理却直——「守物人死了不怕——怕的是物先觉得没人要它。」",text:"铸剑世家工坊角上，独臂客在给一口枯而不涸的老井掸灰，一下一下，像在给它梳头。「它不是我的，是大家的。」独臂客摆摆手，「我就是替大家看着。你今天看它一眼，你也算半个守的。」独臂客直起腰看着你：「客人，你信不信——东西也挑人。它今天让你站住了脚，说明它认你。」",options:[{label:"坐下陪独臂客说说话",goto:1,effect:void 0},{label:"「我有正事，赶路要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"独臂客没追出来。你走了几里地，越想越不对——人家守了几十年的东西，你一句「破烂」就打发了。回头补一句的时候，独臂客正围着一口枯而不涸的老井忙，见了你也不提方才的事，只说：「回来了？搭把手。」你愣是没说出道歉的话——他已经把它翻篇了。"}}]},{xinglu:"是岁铸剑世家工坊一课。独臂客把话说到根上——「守的年头久了，它就是家。」",text:"「最难的不是守，是没人懂。」独臂客笑笑，「懂的人不来，来的人不懂——守着守着就只剩你一个人了。」「没人懂的时候，我就跟它说话。」独臂客笑了，「你别笑——说来说去，说着说着，懂的人就来了。比如你，今天就懂了三分。」「往后你路过，来看它一眼。」独臂客说，「不用你守——看一眼，它就多活一天。这买卖便宜吧？」",options:[{label:"「您守的哪里是物。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"受独臂客所托，允诺路过时看顾一口枯而不涸的老井"},text_after:"你把来处和去处都念了。念完独臂客笑得眼睛眯成一条缝：「好了，你们认识了。往后你不管走多远，它都算你认识的东西——人这辈子，认识的东西多了，心里就宽。」"}},{label:"「我记性不好。」",end:!0,effect:{stat:{wuxing:1},text_after:"「记性不好的人，」独臂客笑了，「就看一眼。眼睛比脑子诚实——看过的东西，忘不掉的。」你回头看了一口枯而不涸的老井一眼。就这一眼，你知道他说得对。"}}]}]},adv_g145_chuanyi:{id:"adv_g145_chuanyi",title:"路遇老妇——在剑冢下院把手艺往下传",mother:"M3",channel:"T2",rarity:1,entry:{node:"kw_jianzhong",chance:.07},stages:[{xinglu:"是岁剑冢下院逢老妇。老妇的话糙，理却直——「教会徒弟饿死师父——说这话的人，手艺本来就不到家。」",text:"你一眼看见一面祖传的皮影——那东西在老妇手里，像长了骨头，每一寸都稳。「外行看手艺，看的是巧。」老妇说，「内行看的是匀——匀了才稳，稳了才久。做人一个理。」老妇忽然把一面祖传的皮影递过来：「来，上手试试？」",options:[{label:"「徒弟难收吧？」",goto:1,effect:void 0},{label:"「我有急事，不多聊。」",end:!0,effect:{stat:{wuxing:1},text_after:"「急事要紧，去忙吧。」老妇摆摆手，忽然又补了一句：「急事里最急的，往往是最不该急的。你路上想想这话。」你出了门越想越不是味儿——他怎么知道你心里正为一件不该急的事上火？"}}]},{xinglu:"是岁剑冢下院一课。老妇把话说到根上——「最好的传法不是教——是让他看你做了三十年。」",text:"「手艺里最难的，不是教会的，是教不会的。」老妇看着你，「你听我讲讲教不会的那部分。」「我师父『饿死』的说法是这样的：」老妇慢慢道，「他把手艺全教给我，自己接的活越来越少。有人笑他傻。他说：徒弟活得好，就是我的老有所养——这比攒银子牢靠。后来他走的时候，来送的全是他教出来的徒弟的徒弟。你说，他饿死了吗？」老妇送你到门口：「来，我这有句话送出门的客人——艺是拿来敬的，不是拿来用的。敬它，它养你一辈子。」",options:[{label:"「这句话，我带走了。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"义",text:"看老妇带徒一下午，学会「骂是疼」的道理"},text_after:"「能传多久？」老妇想了想，「看天。可我告诉你我的算法：只要还有人肯为一个细节较真——这门手艺就活着。你今天盯着我这活看了半晌，就在较真。所以今天，它又多活了一天。」"}},{label:"「与我何干，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「道理是会讲。」老妇不恼，「可我讲了三十年，徒弟们信了——你嘴上不信，眼睛信了。你进来到现在，眼睛没离开过它三回。」你哑口无言。他笑着送你出门：「不信没关系，手艺等得起。它等你一辈子，我都等得起。」"}}]}]},adv_g146_haiyuan:{id:"adv_g146_haiyuan",title:"妇人在岛链渔村替故人还愿",mother:"M4",channel:"T3",rarity:2,entry:{node:"qd_yucun",chance:.09},stages:[{xinglu:"是岁岛链渔村逢妇人。妇人的话糙，理却直——「我一辈子还不完的愿，就是我这辈子最富的家底。」",text:"妇人在岛链渔村等人，等了一个没有地址的人——他要送的是一份没还清的人情。「我跟他打了一辈子交道，就欠这一件。」妇人把一份没还清的人情翻过来给你看，「你看这磨痕——都是他亲手磨的。他磨的时候念的什么，我大概知道。所以这愿，我认。」妇人看着你：「你说，人走了以后，到底知不知道我们还在替他办事？」不等答，他自己接了：「知不知道都要办——这是我的事，不是他的事。」",options:[{label:"「帮您辨认这页纸。」",goto:1,effect:void 0},{label:"「故人的东西，留着何用。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何必？」妇人站住了，回头看你，「你也有一天会走。你走的时候，愿没还完的滋味，你尝过才知道。我劝你一句——趁身边人都在，把该说的话说了，该办的事办了。别像我，净走夜路。」他走了，你的脚步比来时重。"}}]},{xinglu:"是岁岛链渔村一课。妇人把话说到根上——「愿这个东西，许的时候轻飘飘，还的时候千斤重。」",text:"「你还愿还出过蹊跷事没有？」妇人忽然问你，「我遇到过一回——你说邪门不邪门。」「讲一个还愿的故事：有个老猎户，临终托我把他攒的一袋盐分给当年一起守山的弟兄。」妇人说，「弟兄散了，我找了四年，七个找到了六个。第七个，去年在狱里寻着——他犯了事。我把盐给他，他捧着哭了半宿，说：哥几个还记着我。出狱那天，他来找我，如今在山上替人守林。你说，一袋盐值什么？可有些时候，一袋盐就是把人从沟里拉上来的绳。」「我走了。」妇人背起行囊，「这愿还完，我就回家种地——把替人还愿的道理，讲给村口的娃娃们听。让他们知道：这世上有一种债，还的是心安。」",options:[{label:"「这碗水，我记着。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"义",text:"为妇人的故人之愿指了路，了却半桩心愿"},text_after:"「尽到心没尽到心，我自己知道。」妇人摇头，「可你说这话，我路上就不孤单了。还愿人最怕的不是路——是没人说一句『够了，可以了』。你说了一句。我记下了。」"}},{label:"「这故事听着累。」",end:!0,effect:{stat:{wuxing:1},text_after:"「帮不上不打紧。」妇人摆摆手，「别缠着我——这话就伤人了。我讨的不是你的帮，是你让一步路。让一步路，天塌不下来。」他让到道旁，先请你走。你从他身边过的时候，忽然觉得这一步，让得自己心里发虚。"}}]}]},adv_g147_zengxing:{id:"adv_g147_zengxing",title:"岛主议会里白送路上的东西的独臂客",mother:"M1",channel:"T1",rarity:2,entry:{node:"qd_yihui",chance:.13},stages:[{xinglu:"是岁岛主议会逢独臂客。独臂客的话糙，理却直——「我一辈子的买卖：本钱是自己出的，利息是天下人的。」",text:"岛主议会的路边，独臂客摆着一串挂在树上的旧草鞋，来者不问，取者不问。「我年轻时走远路，饿昏在道上，是个不认识的老丈给了我半块饼。」独臂客说，「那半块饼我记了四十年。我这一串挂在树上的旧草鞋，就是还他那半块——还不上他本人，就还给他那样的路人。」独臂客把东西塞到你手里：「拿着。别谢——要谢，往后你也给别人备一份。」",options:[{label:"「我取一份，谢谢。」",goto:1,effect:void 0},{label:"「天下哪有白给的好事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「收买人心？」独臂客愣了一下，随即苦笑，「我要能收买人心，先把我自己这颗买服帖——它总嫌我瞎折腾。」他把东西收回，也不恼，「客人防着点也好。可你记住：天下收买人心的，都要你报答；我什么都不要——你要是连不要报答的都不敢信，这世道可就真没救了。」他这话说得平静，你却走得脸热。"}}]},{xinglu:"是岁岛主议会一课。独臂客把话说到根上——「我送的不是东西，是「有人管你」这句话。」",text:"「赠了这些年，也有糟心事。」独臂客说，「讲一件，你别学我现在的脸色。」「那年来了个贼，夜里偷我的东西不说，还砸了我的牌子。」独臂客说，「我第二天照样摆，牌子重写一块，添了四个字：『夜路慢行』。后来那贼又来——这回是白天，红着脸放下一捆柴，一句话没说走了。」独臂客呵呵地笑，「你瞧，善这东西不咬人，它泡人。泡久了，铁石心肠也软。」「记住这条道的规矩。」独臂客指指一串挂在树上的旧草鞋，「用的时候想着点别人，够用的就别多拿——这不是我的规矩，是路自己的规矩。守住了，这东西就一直有。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"恩",text:"在岛主议会白得一份干粮，后来也学着挂了一壶茶"},text_after:"你收下了。那包东西在行囊里放了很久，一直没舍得吃——不是舍不得，是想起独臂客说的「路上有人惦记」，就觉得这世上怎么走都走不黑。后来你也学他，在自家门前挂了壶凉茶。挂上去那天你才懂：那不是茶，是把当年受的那份踏实，接着往下传。"}},{label:"「我不信这些。」",end:!0,effect:{stat:{wuxing:1},text_after:"「哄你？」独臂客笑了，「我哄你做什么？我又不要你的钱、不要你的命。我哄你，你就信了天下还有点好事——这买卖我亏了还是赚了？」他把东西又塞回你怀里，「拿着。信不信由你——东西是真的，渴了是真的，就这么简单。」"}}]}]},adv_g148_shouye:{id:"adv_g148_shouye",title:"在望仙崖，夜里替人醒着的独臂客",mother:"M2",channel:"T2",rarity:1,entry:{node:"qd_wangxianya",chance:.08},stages:[{xinglu:"是岁望仙崖逢独臂客。独臂客的话糙，理却直——「守夜不图别的——图鸡叫的时候，家家还都是囫囵的。」",text:"你夜宿望仙崖，半梦半醒间听见独臂客的脚步声一遍遍过去——一夜没停。「夜里我谁也不查。」独臂客说，「我就是走。走给睡的人听——听见脚步，贼不敢动，病人心安，失眠的知道天总会亮。我这一双脚，是望仙崖的定心丸。」「夜里的事，你遇上过么？」独臂客问你，「遇上过就知道我这盏灯的用处了。」",options:[{label:"「陪您走一段。」",goto:1,effect:void 0},{label:"「守夜的能有什么出息。」",end:!0,effect:{stat:{wuxing:1},text_after:"「出息？」独臂客笑了，「我这行没出息——没出息到二十年没人抢。可你想想，谁夜里敢不睡？不是我不想睡，是望仙崖几百户人拿觉换了我的不睡。」他敲了敲一段堤坝的巡查路，「出息这东西，白天论的。夜里的账，另算。」你将信将疑地走了。后来你在异乡的夜里病倒，是个守夜的老人照看了你——那一刻你想起这句话，眼睛忽然就热了。"}}]},{xinglu:"是岁望仙崖一课。独臂客把话说到根上——「白天是人管人，夜里是心管心——守夜守的就是那颗不该动的心。」",text:"「你以为守夜就是防贼？」独臂客摇头，「夜里的事，十件有九件不是贼。」「那回真险，是山洪。」独臂客说，「后半夜我听见上游水声不对——平年这时候是涓涓的，那晚是闷雷似的。我挨家砸门，砸了四十七扇。水进村的时候，人都站到坡上了。第二天清点，一只鸡都没少。后来官府来查，问谁先发现的——我说没人发现，水自己来的。他们信了。我为什么不说？说了，下回还得我去砸门——我乐意砸，可功劳这东西，一人占了，别人就不干了。」「天快亮了。」独臂客打了个梆，「五更，天下太平。你听——鸡都叫了。这就是守夜人的一天：什么都没发生，就是最大的事。」",options:[{label:"「您的班，值得。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"恩",text:"陪独臂客守了半宿一段堤坝的巡查路，学会「夜里的另一半」"},text_after:"天亮了。你按独臂客教的走了那条新路——果然避开了塌方段。回头望，独臂客已经收了灯，正往回走。他的背影在晨光里瘦得像根梆子，可你觉得，这一夜望仙崖的太平，全是这根梆子敲出来的。"}},{label:"「别拦着我，我要赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」独臂客指指自己的眼睛，「我这双眼二十年没睡过一个整觉——望仙崖每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g149_shiyi:{id:"adv_g149_shiyi",title:"妇人在沉没宫门替失物寻主人",mother:"M6",channel:"T3",rarity:1,entry:{node:"lg_gongmen",chance:.1},stages:[{xinglu:"是岁沉没宫门逢妇人。妇人的话糙，理却直——「每件遗物背后都站着一个着急的人——我急他所急。」",text:"妇人见你打量一筐孩子丢在路边的玩物，主动开了口：「别看它们破——件件都有来处，件件都在等人。」「有人笑我守着一堆破烂。」妇人不恼，「我说你不懂——破烂搁在你家是破烂，搁在我这儿，是有主的。只等它的主人哪天想起来。人这一辈子，谁没落下过点什么？」「客人有闲功夫没有？」妇人半开玩笑，「搭把手，帮我给这箱子归归类。你归过的，我记下——算你在这行挂个号。」",options:[{label:"「这故事有意思，讲讲。」",goto:1,effect:void 0},{label:"「这行当，没出息。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不会找？」妇人叹口气，「客人，会找的人，丢的都是值钱东西。不会找的——老人丢了，孩子丢了，痴了的人丢了。他们自己找不了，家里人找疯了。我这行拾的，一半是物，一半是人。」他说完不再看你。你走出去几步，觉得方才那句话，轻佻得不像自己的。"}}]},{xinglu:"是岁沉没宫门一课。妇人把话说到根上——「遗落的东西不会说话——可它们都在等人。」",text:"「你以为失物最怕丢？」妇人说，「不。失物最怕的，是被它主人彻底忘了。」「那件一文不值的，是半只风筝。」妇人从柜里捧出来，「碎得没法再飞了。是个娃丢的——他爹重病，他放了一天风筝，说放完了爹就好了。爹没好，走了。风筝也丢了。」妇人声音低下去，「我找了他四年。找到时那娃已经不哭了，只说了句：叔叔，风筝回来了，是不是爹也记得回来？我答不上来。我把风筝给他，他把他爹留的一枚旧扣子给我——说换。我没推。我库里的东西，就数这件最贵。」妇人把册子递给你看：「客人，失物账一页一页都在这儿。你帮不上不要紧——记住：往后你丢了东西，先想想它在谁手里；捡了东西，先想想它归谁。这两句话做到了，我这行就算白教了你。」",options:[{label:"「您守的不是破烂。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"义",text:"在沉没宫门帮妇人归类失物，替七户人家拆了死结"},text_after:"你认出了包袱上的字——是北边某府的馆阁体，还带着军中的写法。「军中的！」妇人一拍大腿，「怪不得我在商旅里问不出——我往驿站问去！」他高兴得像捡了宝，拉着你的手直摇：「客人，你这一眼，顶我三个月的腿。」"}},{label:"「东西丢了再买就是。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人就痴人。」妇人坦然得很，「这世上总得有人痴——都精明着，丢的东西就真没了。你精明你的，我痴我的。哪天你精明不动了、累了，我这一屋子痴，兴许还能给你焐焐手。」"}}]}]},adv_g150_wenlu:{id:"adv_g150_wenlu",title:"清瘦老者在龙骨回廊只问不答",mother:"M7",channel:"T1",rarity:1,entry:{node:"lg_huilang",chance:.07},stages:[{xinglu:"是岁龙骨回廊逢清瘦老者。清瘦老者的话糙，理却直——「天下没有蠢问题，只有不肯问的人。」",text:"你路过龙骨回廊，清瘦老者拦住你：「客人，问你个事——你答不上来不要紧。」「我年轻时最烦人提问。」清瘦老者笑了，「后来自己开了店——才发现，肯问你的人才拿你当回事。不问的人，早就把你算计好了。问，是信。」「你替我想想。」清瘦老者把一张写着问句的纸条递过来，「这个问题挂了三年没人答。你说说看——答不好也不要紧。」",options:[{label:"「这个利息，我还。」",goto:1,effect:void 0},{label:"「卖关子，无聊。」",end:!0,effect:{stat:{wuxing:1},text_after:"「干活要紧，对。」清瘦老者点头，「可我问你的不是话——是你干活的那个『为什么』。差事是别人派的，为什么干是你自己的。这两个不搭上，你干一辈子，也就是个工钱。」他把纸条又塞了塞，「不搭嘴。可你总有一天会想知道——到那天，纸条上见。」"}}]},{xinglu:"是岁龙骨回廊一课。清瘦老者把话说到根上——「我不教人——我提问题，路让人自己走。」",text:"「问了一辈子，也栽过跟头。」清瘦老者说，「讲一件——讲完你就知道，问题也能伤人。」「三十年挂着的那个问题是：人这一生，是答案重要，还是问得对重要？」清瘦老者缓缓道，「年轻时我赌答案是重要的——答对了就赢了。后来发现，答对的都有过期的一天。如今我改赌了：问得对重要。问对了，答错了能重来；问错了，答对了也是白答。」清瘦老者笑了笑，「你呢？你怎么赌？不用现在答——这个问题，现在也归你了。」清瘦老者把一张纸条郑重推给你：「这个问题归你了。不急——哪天想通了，丢进我这竹筒里就行，人不用来。问题认字不认人。」",options:[{label:"「看，还是觉得——我记下了。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"恩",text:"在龙骨回廊答了清瘦老者一问，得了他一句「认真想的人自带先生」"},text_after:"你收下那个问题，揣了三年。第三年秋天你在异乡的田埂上想通了——回去时清瘦老者的店还开着，你把答案丢进竹筒。后来听说他每逢初一就摇竹筒听响，笑着说：「这条又满了。」你不知道他说的哪条是你——可你知道，有个人的问题，替你养了三年的心。"}},{label:"「我从不问路，只看脚下的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」清瘦老者把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g151_jizhang:{id:"adv_g151_jizhang",title:"在鲛人遗族聚落，替人情记着账的盲眼老者",mother:"M8",channel:"T2",rarity:2,entry:{node:"lg_jiaoluo",chance:.12},stages:[{xinglu:"是岁鲛人遗族聚落逢盲眼老者。盲眼老者的话糙，理却直——「情分这东西，不记账就散——散了再聚，就生分了。」",text:"盲眼老者见你生面孔，先递茶再开口：「客人路过的吧？有没有账，都坐坐——我这儿不只是记账的。」「有人问我，死人欠的账记来做什么。」盲眼老者说，「记。儿子长大来翻账——看见他爹当年受过谁的恩、还过谁的债，他就知道自己是个什么根底。账本就是家谱，还是最老实的那一页。」盲眼老者打量你一番：「客人面生——有没有旧账落在我这儿？有的话，报个名姓，我一翻便知。」",options:[{label:"「头一页，讲讲。」",goto:1,effect:void 0},{label:"「我不欠谁的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「闲事？」盲眼老者笑了，「张家的牛吃了李家的苗，是闲事；王家的娃读了书没人束脩，是闲事；你小时候发高热，邻家婶子背你走过三条街——也是闲事。这世上的情分，全是『闲事』堆出来的。我记的就是这些——你说的正事，反倒用不着我记。」"}}]},{xinglu:"是岁鲛人遗族聚落一课。盲眼老者把话说到根上——「钱账好记，情账难记——难记的才需要人记。」",text:"「你见过两家人为一笔账断了二十年的来往么？」盲眼老者说，「我接手过。」「记错的那笔，是早年一个后生替他病重的爹来还账。」盲眼老者声音哑了，「我记成『还清』，其实差着半吊。他爹咽气前问起，还念叨着那半吊。等我发现，人已经没了，账差了，说不清了。」盲眼老者翻开账本给我看——那页边上有行小字：「错在我，补录于三年后，按利全还，还账人：他儿子。」——「他儿子在外头挣了三年，回来把半吊连本带利还了，还非要多还一份。我说不该多。他说：我爹没还完的账，我替他记得体面些。从那天起，我每笔记三遍。」盲眼老者把茶续满：「别急着走。听账人的道理，不在账上——在你听完以后，回头看你自家那本账。人人心里都有一本，只是没人替你誊清。」",options:[{label:"「这碗茶，敬记账人。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"恩",text:"帮盲眼老者誊账一页，字正心平，得了保管员三分真传"},text_after:"「当得起什么。」盲眼老者连连摆手，「我这行，说到底是替人管着念想。念想是他们的，我只是个保管员。」可你看得出来，他说这话时腰板挺得笔直——一个一辈子被几千户人信着的人，那份挺直，是拿三十年的笔一笔一笔撑起来的。"}},{label:"「记账记成痴，何苦。」",end:!0,effect:{stat:{wuxing:1},text_after:"「白记？」盲眼老者居然点头，「你说得对——十笔情账，有三笔是白记的。可剩下七笔呢？」他翻开册子给我看密密麻麻的还账记录，「人情是靠不住——可总得有人头一个信。我信了三十年，换回这七本册子的『还』字。你赌人不靠得住，你赌输了也就输了；我赌人靠得住，我赢得一街的太平。这笔账，你自己算。」"}}]}]},adv_g152_shouwu:{id:"adv_g152_shouwu",title:"补给岛的一课：驼背阿婆守着一件旧物",mother:"M5",channel:"T3",rarity:2,entry:{node:"nh_bujidao",chance:.07},stages:[{xinglu:"是岁补给岛逢驼背阿婆。驼背阿婆的话糙，理却直——「守到后来，分不清是我守它，还是它守我。」",text:"驼背阿婆在补给岛守了一囤救命粮，见你打量，先开口说了它的来历。「这东西看着孤，其实不孤。」驼背阿婆指给你看，「它身上有几十年的手印。守它的人一代传一代，手印摞手印——它比谁的家底都厚。」「你要是赶路，就歇口气再走。」驼背阿婆指指旁边，「你歇的这会儿，它也算没白站着。」",options:[{label:"坐下陪驼背阿婆说说话",goto:1,effect:void 0},{label:"「我有正事，赶路要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「闲事？」驼背阿婆不恼反笑，「天下的正经事，起头都是闲事。守桥的、修路的、点灯的——起初谁不说他们闲？」你走远了，那句「闲事」在你耳朵里转了一路，越转越不像闲事。"}}]},{xinglu:"是岁补给岛一课。驼背阿婆把话说到根上——「它站了几百年，我陪它站几年，不算多。」",text:"「我师父守它三十年，我接了二十年。」驼背阿婆说，「加起来五十年，还没它站着的年头长。」「最险的那年，我自己都快没了。」驼背阿婆拍拍胸口，「躺在这儿想：我要是走了，它怎么办？就为这个念头，我又站起来了。守物守到这份上，命都是它给的。」驼背阿婆站起身，最后擦了一遍一囤救命粮：「天不早了。守物人的话就这么多——你要记，就记一句：物在人守。人要是都不守了，物就真没了。」",options:[{label:"「我记下了。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"义",text:"与驼背阿婆共守一囤救命粮一夜，学会守物的规矩"},text_after:"你陪驼背阿婆坐到日头偏西。临走他说：「今天这一坐，比擦十年灰有用。」你问为什么。他说：「东西怕的不是旧，是没人坐。有人肯坐，它就还是个去处。」"}},{label:"「天下旧物多了，管不过来。」",end:!0,effect:{stat:{wuxing:1},text_after:"「管不过来是实话。」驼背阿婆点头，「可你今天站在它跟前这么久——它就多认得一个人。一个一个攒，攒着攒着，就有人管了。」"}}]}]},adv_g153_chuanyi:{id:"adv_g153_chuanyi",title:"路遇驼背阿婆——在海市把手艺往下传",mother:"M3",channel:"T1",rarity:2,entry:{node:"nh_haishi",chance:.09},stages:[{xinglu:"是岁海市逢驼背阿婆。驼背阿婆的话糙，理却直——「我把一辈子拆成手艺，你拿去接着活。」",text:"海市里最齐整的就是一册手抄的方子簿——驼背阿婆说，家伙什齐整，手艺才齐整。驼背阿婆教你认一册手抄的方子簿的门道：「你看这儿，磨了三十年才有的包浆。手艺也一样——急不来的东西，才立得住。」「来，站我旁边看。」驼背阿婆招招手，「看一遍，顶听十遍。」",options:[{label:"「愿闻其详。」",goto:1,effect:void 0},{label:"「这些老规矩，过时了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「急事要紧，去忙吧。」驼背阿婆摆摆手，忽然又补了一句：「急事里最急的，往往是最不该急的。你路上想想这话。」你出了门越想越不是味儿——他怎么知道你心里正为一件不该急的事上火？"}}]},{xinglu:"是岁海市一课。驼背阿婆把话说到根上——「手艺不传，人就白活一遭。」",text:"「我这一册手抄的方子簿差点断在一桩事上。」驼背阿婆摩挲着它，「你听听——听完你就明白手艺人为什么较真。」「我为什么当着徒弟面拆了重做？」驼背阿婆说，「因为躲一次错，徒弟就学会藏错；认一次错，徒弟就学会认错。手艺上的毛病小，人心上的毛病大——我宁可在活上丢脸，不在人上丢魂。」「我这一册手抄的方子簿，早晚传给肯下苦功的人。」驼背阿婆望着作坊，「也许是我徒弟，也许是徒弟的徒弟，也许——是个今天来歇脚的路人。缘分这东西说不准。」",options:[{label:"「敬艺二字，受教了。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"义",text:"在海市受驼背阿婆一课，悟「敬艺」之理"},text_after:"你对完那册子，指出两处错字。驼背阿婆当即改了，改完郑重其事地给你作了个揖：「手艺传得走不走样，就差这一个字两个字。你今天替这门手艺把住了关——往后它传到哪儿，都有你一份。」"}},{label:"「与我何干，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要绝就绝。」驼背阿婆淡淡地说，「手艺绝不绝，不看我这代人喊多响——看下代人肯不肯弯腰。我弯了三十年腰了，够了。绝了也不冤：它来的时候有人敬，走的时候有人送，全始全终。」你出门时回头看了一眼，驼背阿婆已经又坐回一册手抄的方子簿前——绝不绝的话撂在那儿，手上的活一天没停。"}}]}]},adv_g154_haiyuan:{id:"adv_g154_haiyuan",title:"在妖市，替故人还愿的老汉",mother:"M4",channel:"T2",rarity:3,entry:{node:"dh_yaoshi",chance:.08},stages:[{xinglu:"是岁妖市逢老汉。老汉的话糙，理却直——「替人还愿这行，赚的不是钱——是夜里睡得着。」",text:"老汉在妖市打听路，手里攥着一份没还清的人情——他在替谁了却一桩心愿。「家里人劝我，人走了就放下。」老汉摇头，「放下是给活人的宽心话。可愿不是包袱——愿是路标。我把这个愿还了，往后他坟头的草，我看着都顺眼。」老汉看着你：「你说，人走了以后，到底知不知道我们还在替他办事？」不等答，他自己接了：「知不知道都要办——这是我的事，不是他的事。」",options:[{label:"「愿闻其详。」",goto:1,effect:void 0},{label:"「路远事烦，别找了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「留着何用？」老汉把一份没还清的人情举起来给你看，「你看它像东西吗？不像了——它是一句没说完的话。话没了，人才真的没了。」他说完自己收好，朝你拱拱手，「客人，话糙了。可这理，你早晚用得上。」"}}]},{xinglu:"是岁妖市一课。老汉把话说到根上——「我不怕愿多——我怕的是没人记得那些愿。」",text:"「说起这个愿的来历，」老汉坐下身来，「得从头讲。」「早点还不上，是因为我放不下脸面。」老汉认了，「当年跟他置气，他托的事我故意拖着。后来他走了，我提着一份没还清的人情在他坟前跪了一夜——第二天启程。你还愿，一半还的是他的愿，一半还的是自己的脸。我这张老脸，路上磨掉了一半，如今才算个人。」老汉把一小撮路上的干粮分给你：「同行一程，就是有缘。这个你拿着——路上的人情，也是愿的一部分。我替故人结的善缘，多一个是一个。」",options:[{label:"「这碗水，我记着。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"恩",text:"捎老汉一程，听了一个还愿人的故事"},text_after:"你帮着辨出了那页纸上的字——缺的那一角，是收信人的名字。老汉盯着那个名字看了许久：「对上了。就差这个字，我在县里翻了三天的户籍。」他抬头时眼眶红了，「客人，你今天不是帮我看字——你是替他把最后一句话，送到了门口。」"}},{label:"「这故事听着累。」",end:!0,effect:{stat:{wuxing:1},text_after:"「累？」老汉笑了，「我讲的累，是别人的命换来的道理。你嫌累，道理不怪你——可道理也不会再来找你。走吧。」你走出去半里，忽然想折回来问问他那花田的事——终究没折。那半里路，你走得比来时快，也比来时轻浮。"}}]}]},adv_g155_zengxing:{id:"adv_g155_zengxing",title:"万妖山来了个白送路上的东西的独臂客",mother:"M1",channel:"T3",rarity:1,entry:{node:"dh_wanyao",chance:.1},stages:[{xinglu:"是岁万妖山逢独臂客。独臂客的话糙，理却直——「我一辈子的买卖：本钱是自己出的，利息是天下人的。」",text:"独臂客在万妖山支着一桶拴在渡口的姜汤，有人取用，他连头都不抬，只说慢用。「起头也有人笑我傻。」独臂客靠着一桶拴在渡口的姜汤坐下，「白摆着，让人白拿。我说你看着——一个月后你再笑。一个月后，笑我的人绕路也来喝一口。」独臂客把东西塞到你手里：「拿着。别谢——要谢，往后你也给别人备一份。」",options:[{label:"「往后还走。」",goto:1,effect:void 0},{label:"「少来这套收买人心。」",end:!0,effect:{stat:{wuxing:1},text_after:"「白给的好事？」独臂客哈哈大笑，「你算算这笔账：我一年搭进去几贯钱，换来这条道上的人夜里敢走、白天敢歇——你说值几贯？好事从来都白给，只是给的人不说。」你把他的话琢磨了一路，到家门口才咂摸出味儿来。"}}]},{xinglu:"是岁万妖山一课。独臂客把话说到根上——「赠出去的每一件，都是投给这世道的一票——投它个好字。」",text:"「你知道最让我高兴的一回是什么？」独臂客卖了个关子，不等你说完就笑了，「不是谁谢我。」「得意的是那边——」独臂客指的远处有户人家，「那家两口子，当年落难，在我这儿白吃了半个月。后来缓过来了，在自家村口也摆了一摊。再后来，那条道上每隔十里就有一摊——不是我摆的。我这一缸茶，泡出了一条道的人心。你说值不值？」独臂客朝你挥挥手：「走吧走吧。东西拿了，话也听了——往后你也是个路上的人了。路上的人认路上的人，一眼就认得。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"恩",text:"在万妖山白得一份干粮，后来也学着挂了一壶茶"},text_after:"「我可没说一定是我。」你摆手。独臂客笑道：「兴许不是。可你今天多站了这半晌——比别人近了一步。这摊子挑人，跟守物挑人一样：挑肯停脚的。」你走出几里地回头望，他还坐在一桶拴在渡口的姜汤边——像路长出来的一部分。"}},{label:"「我不信这些。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不算上你。」独臂客点头，「我的账是我的。可你走在这条道上，喝过路边的井水、走过别人修的桥、睡过别人盖的亭子——这些账都跟我一样，没人跟你要过。」他拍拍一桶拴在渡口的姜汤，「不用你算我的账。哪天你想起这世道不全是黑的，就够了。」"}}]}]},adv_g156_shouye:{id:"adv_g156_shouye",title:"化形妖城来了个夜里替人醒着的白发老丈",mother:"M2",channel:"T1",rarity:2,entry:{node:"dh_huaxing",chance:.13},stages:[{xinglu:"是岁化形妖城逢白发老丈。白发老丈的话糙，理却直——「夜里的事，白天看不见——看不见不等于没有。」",text:"白发老丈守在一仓新入的粮食旁，火光把他的影子拉得很长，见你近前，先问了句：「夜里赶路，有事？」「守夜人最要紧的不是胆，是觉浅。」白发老丈笑道，「风吹草动，我在三里外的被窝里都能竖起耳朵。这不是本事——这是把心搁在化形妖城搁了二十年，搁熟了。」「夜深了。」白发老丈看看天，「你歇你的。我照旧巡我的——鸡叫之前，你听不见一点动静。这是我的保票。」",options:[{label:"「遇上过，才知灯金贵。」",goto:1,effect:void 0},{label:"「黑路我自己认得。」",end:!0,effect:{stat:{wuxing:1},text_after:"「认得黑路是好事。」白发老丈没拦你，「可你认得的是路——路认不认你，两说。去年有个自认得路的，掉进了拆了半截的桥坑里，躺了一夜——他不知道那坑，我知道。」他举灯照了照那个方向，「喏，就那儿。坑还在，天亮我得上报。」你没再犟，跟着他走了那条亮路。"}}]},{xinglu:"是岁化形妖城一课。白发老丈把话说到根上——「夜里的规矩比白天大——因为夜里没人看着，全凭自觉。」",text:"「守夜二十年，我就遇过一回真险。」白发老丈说到这儿，摸了摸一仓新入的粮食。「夜里的事，是病人、是醉汉、是走投无路的人。」白发老丈一样样数给你听，「产妇半夜要生，是我跑去接的稳婆；醉汉躺在冰边上，是我拖回来的；还有个后生想跳河——我在河边陪他坐到天亮，一句话没劝，他就自己回去了。」白发老丈叹口气，「白天的人都以为夜里干净。夜里最不干净——夜里的难处，都是白天咽下去的。」白发老丈把灯吹熄了——天光已经泛白。「灯不用了。」他说，「灯是夜里的东西。你记住这盏灯照过你——就够了。」",options:[{label:"「您的班，值得。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"恩",text:"陪白发老丈守了半宿一仓新入的粮食，学会「夜里的另一半」"},text_after:"你带走了那一半话。夜里赶路时你学着白发老丈的样子，给后来的人照个亮。有回一个后生问你是谁，你说：「一个守夜的教我的——夜里的另一半，留给夜里的人。」后生似懂非懂。可他往后也给人照亮了——白发老丈的灯，就这么传到了你手上。"}},{label:"「别拦着我，我要赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「名堂？」白发老丈把灯举起来，「你看这灯照多远——三步。可走夜路的人，缺的就是这三步。」他放下灯，「名堂是白天的事。我夜里不图名堂——图的是化形妖城的狗都不叫唤。狗都不叫，就是真太平。你要图名堂，白天去图；你要图太平，咱们才是一路的。」"}}]}]},adv_g157_shiyi:{id:"adv_g157_shiyi",title:"在佛国香市，替失物寻主人的老人",mother:"M6",channel:"T2",rarity:2,entry:{node:"xm_xiangshi",chance:.09},stages:[{xinglu:"是岁佛国香市逢老人。老人的话糙，理却直——「我守着一屋子没人要的东西，其实守着一屋子没人讲完的故事。」",text:"老人收着一册记满失物的旧簿，逢人先问一句「你可认得……」——问了十年，问了满城的摇头。「这一屋子，全是三年没人认的。」老人拍了拍一册记满失物的旧簿，「按理可以处置了。我不——三年找不到主人，我就再等三年。东西等得起，等不起的是万一哪天，那个找它的人来了，东西没了。」「客人有闲功夫没有？」老人半开玩笑，「搭把手，帮我给这箱子归归类。你归过的，我记下——算你在这行挂个号。」",options:[{label:"「这故事有意思，讲讲。」",goto:1,effect:void 0},{label:"「这行当，没出息。」",end:!0,effect:{stat:{wuxing:1},text_after:"「没出息。」老人笑了，「对——没出息，饿不死，也发不了。可你告诉我，什么行当能让人二十年睡得着觉？我这行能。我每送回一件东西，就有一户人家少一夜的睡不着。」他拱拱手，「出息是活给别人看的，觉是自己睡的。慢走。」"}}]},{xinglu:"是岁佛国香市一课。老人把话说到根上——「每件遗物背后都站着一个着急的人——我急他所急。」",text:"「拾遗这行，也有发懵的时候。」老人说，「讲一件，你听听值不值。」「那件一文不值的，是半只风筝。」老人从柜里捧出来，「碎得没法再飞了。是个娃丢的——他爹重病，他放了一天风筝，说放完了爹就好了。爹没好，走了。风筝也丢了。」老人声音低下去，「我找了他四年。找到时那娃已经不哭了，只说了句：叔叔，风筝回来了，是不是爹也记得回来？我答不上来。我把风筝给他，他把他爹留的一枚旧扣子给我——说换。我没推。我库里的东西，就数这件最贵。」「天不早了。」老人点起灯，「我这儿夜里也开门——丢东西的人，是不分时辰的。你慢走，路上小心别落了东西。落了也不要紧——这世上还有我这样的人。」",options:[{label:"「替您跑这一趟。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"义",text:"在佛国香市学了两句话：丢了先想它在谁手里，捡了先想它归谁"},text_after:"你认出了包袱上的字——是北边某府的馆阁体，还带着军中的写法。「军中的！」老人一拍大腿，「怪不得我在商旅里问不出——我往驿站问去！」他高兴得像捡了宝，拉着你的手直摇：「客人，你这一眼，顶我三个月的腿。」"}},{label:"「东西丢了再买就是。」",end:!0,effect:{stat:{wuxing:1},text_after:"「拾不过来。」老人坦白得很，「天下的失物，我一辈子拾不完。可我多拾一件，世上就少一件没着落的。你这话跟师父当年说的一模一样——他后来呢？他拾了一辈子。」他拿起册子，「拾不过来，就一件一件来。日子长着呢。」"}}]}]},adv_g158_wenlu:{id:"adv_g158_wenlu",title:"佛骨塔里只问不答的老人",mother:"M7",channel:"T3",rarity:1,entry:{node:"xm_foguta",chance:.08},stages:[{xinglu:"是岁佛骨塔逢老人。老人的话糙，理却直——「答疑解惑是先生的事——我只负责让你自己解。」",text:"你被老人叫住：「别急着走。你说——人为什么要问路？」「你说人为什么要问路？」老人自问自答，「因为路认生。认生的东西，你不问它，它就骗你——这是路教的，我只是转述。」「你替我想想。」老人把一张写着问句的纸条递过来，「这个问题挂了三年没人答。你说说看——答不好也不要紧。」",options:[{label:"「我是在奔着一条路。」",goto:1,effect:void 0},{label:"「问那么多做什么，干活要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「干活要紧，对。」老人点头，「可我问你的不是话——是你干活的那个『为什么』。差事是别人派的，为什么干是你自己的。这两个不搭上，你干一辈子，也就是个工钱。」他把纸条又塞了塞，「不搭嘴。可你总有一天会想知道——到那天，纸条上见。」"}}]},{xinglu:"是岁佛骨塔一课。老人把话说到根上——「问句是钩子——鱼上不上钩不要紧，水被搅活了就行。」",text:"「有人骂我，说问了半天屁用没有。」老人居然点头，「他骂得对。你听听怎么回事。」「骂我的那位，是个急性子的商人。」老人点头认了，「他问怎么发财，我不答，反问他：你发财是要给谁看？他气得跳脚，骂了半天走了。半年后他回来，红着脸给我作揖——说他那半年净想我这问题，生意反而稳了：不图人看的买卖，才做得长。」老人笑道，「你看，我挨一句骂，换他半条正路——这账，赚。」老人把一张纸条郑重推给你：「这个问题归你了。不急——哪天想通了，丢进我这竹筒里就行，人不用来。问题认字不认人。」",options:[{label:"「利息我必还。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"恩",text:"在老人店里吵了一架，各自往前挪了半步"},text_after:"「看，还是觉得——这一句你带走了。」老人满意地送你出门。后来你在生意上、恩怨里、抉择前，无数次问自己这一句。它不能替你做对的事——可它让你少做了许多自以为对的事。你从此逢人便传这句话，传的时候都说是从一个怪老头那儿听来的。"}},{label:"「故弄玄虚，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「从不问路？」老人看着你，忽然认真了，「客人，我不拦你。可我送你一句话：不问路的人，不是路盲——是路盲里胆子最大的。老天爷不在乎你问不问，它只管把你引到岔路口。你凭本事闯，闯对了是命大，闯错了——」他顿了顿，「没有人给你收尸。走吧。这话搁这儿，你哪天想起，算我的。」"}}]}]},adv_g159_jizhang:{id:"adv_g159_jizhang",title:"泉眼驿寺来了个替人情记着账的盲眼老者",mother:"M8",channel:"T1",rarity:1,entry:{node:"xm_yisi",chance:.09},stages:[{xinglu:"是岁泉眼驿寺逢盲眼老者。盲眼老者的话糙，理却直——「账本比人活得长——我把账记清楚，情分就比人长寿。」",text:"盲眼老者正往一面写满还账记号的墙上添一笔，添完念给你听：「某年某月，某人还清。」——念得像唱。「记账三十年，我笔底下没错过一文。」盲眼老者说，「不是我算术好——是我每笔记两遍、念一遍、过三天再核一遍。账这东西，错一笔，一街的信就塌了。」盲眼老者递给你一盏茶：「先别急着走。听我说说这账本上的头一页——听完你就知道，账不是冰的。」",options:[{label:"「我誊这页。」",goto:1,effect:void 0},{label:"「你这行当，多管闲事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「闲事？」盲眼老者笑了，「张家的牛吃了李家的苗，是闲事；王家的娃读了书没人束脩，是闲事；你小时候发高热，邻家婶子背你走过三条街——也是闲事。这世上的情分，全是『闲事』堆出来的。我记的就是这些——你说的正事，反倒用不着我记。」"}}]},{xinglu:"是岁泉眼驿寺一课。盲眼老者把话说到根上——「账不怕欠——怕的是没人记。记着，就还有还的一天。」",text:"「我师父传我的时候，只考了我一件事。」盲眼老者说，「不是算术——你猜猜是什么。」「记错的那笔，是早年一个后生替他病重的爹来还账。」盲眼老者声音哑了，「我记成『还清』，其实差着半吊。他爹咽气前问起，还念叨着那半吊。等我发现，人已经没了，账差了，说不清了。」盲眼老者翻开账本给我看——那页边上有行小字：「错在我，补录于三年后，按利全还，还账人：他儿子。」——「他儿子在外头挣了三年，回来把半吊连本带利还了，还非要多还一份。我说不该多。他说：我爹没还完的账，我替他记得体面些。从那天起，我每笔记三遍。」「替我记一笔。」盲眼老者忽然说，「就说：今天有个过路的客人，坐下来听完了整本账。这一笔记下——你也是账里的人了。」",options:[{label:"「这句话，我带走了。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"恩",text:"听盲眼老者讲大饥年保账的旧事，识得一页纸的分量"},text_after:"你替他跑了一趟，把一册抄本送到了邻县。收账的是个白胡子老者，翻开一看就红了眼：「还有人记着这笔……」你回程时盲眼老者已在门口候着——他不要你讲细节，只问了一句：「送到就行了？」你说送到了。他长出一口气：「好。这一笔，两头都活了。」"}},{label:"「账本又不是靠山。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何苦？」盲眼老者笑了，「我这一柜账，年年有人来对、来还、来谢——我苦什么？苦的是你们这些不记的：受了恩转脸就忘，欠了债装不知道——你以为你们轻省？你们那才是苦——账在心里烂着，夜夜硌得慌。我睡得着，就凭我这柜子。」"}}]}]},adv_g160_shouwu:{id:"adv_g160_shouwu",title:"十八峒总寨来了个守着一件旧物的独臂客",mother:"M5",channel:"T2",rarity:2,entry:{node:"nj_bazhai",chance:.13},stages:[{xinglu:"是岁十八峒总寨逢独臂客。独臂客的话糙，理却直——「守到后来，分不清是我守它，还是它守我。」",text:"十八峒总寨角上，独臂客在给一座老水闸掸灰，一下一下，像在给它梳头。「当年交给我的时候说，守到守不动为止。」独臂客摩挲着一座老水闸，「我算了算，还早。我还能守——它也还站得住。」「你要是赶路，就歇口气再走。」独臂客指指旁边，「你歇的这会儿，它也算没白站着。」",options:[{label:"帮着擦一遍一座老水闸",goto:1,effect:void 0},{label:"不搭话，绕着走",end:!0,effect:{stat:{wuxing:1},text_after:"「赶路要紧，是正经话。」独臂客点头，「可我告诉你——路走完了，能想起来的，往往不是路上多快，是谁让你停了一脚。你走吧，我不拦。」你走出半里地，脚步不自觉慢了下来。"}}]},{xinglu:"是岁十八峒总寨一课。独臂客把话说到根上——「东西旧了不怕，怕的是没人认它。」",text:"「有年发大水，」独臂客望着一座老水闸，「别人都撤了，我守着它没走。」「没人懂的时候，我就跟它说话。」独臂客笑了，「你别笑——说来说去，说着说着，懂的人就来了。比如你，今天就懂了三分。」「守物人不说谢。」独臂客说，「你要真帮了它，它自己会谢你——哪天你落难了，想起这世上有一处地方，有个东西好好站着——你就暖和了。」",options:[{label:"「这话我记一辈子。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"恩",text:"在十八峒总寨听独臂客讲守一座老水闸的道理，助守一日"},text_after:"你帮着擦完了。手上的灰蹭了一袖子，心里却出奇地熨帖。独臂客看着擦亮的一座老水闸，半天说了句：「行了，今天这一遍，值。」你走出很远才咂摸出味儿来——他谢的不是你，是它今天又被人认真对待了一回。"}},{label:"「天下旧物多了，管不过来。」",end:!0,effect:{stat:{wuxing:1},text_after:"「管不过来是实话。」独臂客点头，「可你今天站在它跟前这么久——它就多认得一个人。一个一个攒，攒着攒着，就有人管了。」"}}]}]},adv_g161_chuanyi:{id:"adv_g161_chuanyi",title:"中年汉子在瘴林把手艺往下传",mother:"M3",channel:"T3",rarity:1,entry:{node:"nj_zhanglin",chance:.09},stages:[{xinglu:"是岁瘴林逢中年汉子。中年汉子的话糙，理却直——「手艺不认血缘，只认肯下苦功的人。」",text:"瘴林里最齐整的就是一面祖传的皮影——中年汉子说，家伙什齐整，手艺才齐整。「手艺这行，学三年，学的是不怕烦。」中年汉子拿起一面祖传的皮影给你比划，「你怕烦，活就糊弄你；你不怕烦，活就给你撑场面。」中年汉子让徒弟先歇了，转过身来：「客人识字吧？帮我看看这册子上的字有没有错的——手艺传得走样，多半是从错字开始的。」",options:[{label:"「这手艺，能传多久？」",goto:1,effect:void 0},{label:"「学这个能挣几个钱？」",end:!0,effect:{stat:{wuxing:1},text_after:"「急事要紧，去忙吧。」中年汉子摆摆手，忽然又补了一句：「急事里最急的，往往是最不该急的。你路上想想这话。」你出了门越想越不是味儿——他怎么知道你心里正为一件不该急的事上火？"}}]},{xinglu:"是岁瘴林一课。中年汉子把话说到根上——「教会徒弟饿死师父——说这话的人，手艺本来就不到家。」",text:"「人家都说教会徒弟饿死师父。」中年汉子把茶碗一放，「我给你讲讲我师父是怎么『饿死』的。」「九个徒弟里走得最远的那个，如今把手艺传到了三个省。」中年汉子满脸得意，「他当年被我骂出门的。走的时候撂话：此生不回来。前年他回来，进门就给我端了盆洗脚水——说师父，我懂了。我问懂什么了。他说：您当年骂我的每一句，如今我都原样骂给我的徒弟。」中年汉子最后擦了一遍手，朝你拱手：「客人慢走。手艺人的话糙，理不糙——你今儿听的这些，够你在别的行当里用一辈子。」",options:[{label:"「敬艺二字，受教了。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"义",text:"在瘴林受中年汉子一课，悟「敬艺」之理"},text_after:"你对完那册子，指出两处错字。中年汉子当即改了，改完郑重其事地给你作了个揖：「手艺传得走不走样，就差这一个字两个字。你今天替这门手艺把住了关——往后它传到哪儿，都有你一份。」"}},{label:"「手艺早晚要绝。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要钱？」中年汉子愣了一下，随即大笑，「我今天一个字没收你钱，还搭了一下午的茶——你要是听成了要钱，那我这一下午白讲了，你的耳朵也白带了。走吧走吧——」他摆摆手，笑骂道，「亏你今天还看了我半天活。看活不看人，你差得远呢。」"}}]}]},adv_g162_haiyuan:{id:"adv_g162_haiyuan",title:"中年汉子在雪原猎场替故人还愿",mother:"M4",channel:"T1",rarity:1,entry:{node:"by_xueyuan",chance:.13},stages:[{xinglu:"是岁雪原猎场逢中年汉子。中年汉子的话糙，理却直——「替人还愿这行，赚的不是钱——是夜里睡得着。」",text:"雪原猎场里，中年汉子捧着一封没寄出去的信出神——你一问，他说这是故人留下的。「他说过，这事办成了，他就了无遗憾。」中年汉子望着一封没寄出去的信，「他走了两年，我走了两万里的路。你说值不值？我不算这个账——我只知道，他临终看我的那一眼，我一辈子忘不掉。」中年汉子看着你：「你说，人走了以后，到底知不知道我们还在替他办事？」不等答，他自己接了：「知不知道都要办——这是我的事，不是他的事。」",options:[{label:"「帮您辨认这页纸。」",goto:1,effect:void 0},{label:"「与我无关，让让。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何必？」中年汉子站住了，回头看你，「你也有一天会走。你走的时候，愿没还完的滋味，你尝过才知道。我劝你一句——趁身边人都在，把该说的话说了，该办的事办了。别像我，净走夜路。」他走了，你的脚步比来时重。"}}]},{xinglu:"是岁雪原猎场一课。中年汉子把话说到根上——「还愿的人不问值不值——问值不值的时候，愿就已经不是愿了。」",text:"「你还愿还出过蹊跷事没有？」中年汉子忽然问你，「我遇到过一回——你说邪门不邪门。」「早点还不上，是因为我放不下脸面。」中年汉子认了，「当年跟他置气，他托的事我故意拖着。后来他走了，我提着一封没寄出去的信在他坟前跪了一夜——第二天启程。你还愿，一半还的是他的愿，一半还的是自己的脸。我这张老脸，路上磨掉了一半，如今才算个人。」「你要是记得今天这故事，」中年汉子说，「往后见着满头白发的还愿人，别笑他痴。给他一碗水——他替这世上所有走了的人，捎着话呢。」",options:[{label:"「我记住了。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"捎中年汉子一程，听了一个还愿人的故事"},text_after:"「尽到心没尽到心，我自己知道。」中年汉子摇头，「可你说这话，我路上就不孤单了。还愿人最怕的不是路——是没人说一句『够了，可以了』。你说了一句。我记下了。」"}},{label:"「愿是虚的，人死了就完了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「完了就完了？」中年汉子站定，认真看你，「人走茶凉是世道。可我把茶端热的这些年，凉不了——你信不信？你今天说这话，是因为还没遇着走的人。遇着了，你会想起我。」他走了，那句话你揣了一路，越揣越沉。"}}]}]},adv_g163_zengxing:{id:"adv_g163_zengxing",title:"剑冢的一课：老汉白送路上的东西",mother:"M1",channel:"T2",rarity:1,entry:{node:"by_jianzhong",chance:.11},stages:[{xinglu:"是岁剑冢逢老汉。老汉的话糙，理却直——「我一辈子的买卖：本钱是自己出的，利息是天下人的。」",text:"你路过剑冢，看见老汉正把一坛埋在路口的清水摆放齐整——摆完冲空荡荡的路作了个揖。「这东西损耗大，我不是不心疼。」老汉笑了，「可我算过另一笔账：一年三百六十五天，总有那么几天，正是有人最需要它的时候。我囤的不是货——是那几天的『正好』。」「帮我记个账呗。」老汉递过来一个小本子，「不是记谁拿了什么——是记今天又有几个人用了它。这账好看，你写一笔。」",options:[{label:"「往后还走。」",goto:1,effect:void 0},{label:"「我不占人便宜。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不占便宜是好品性。」老汉点头，「可我这不叫便宜——叫过路钱。你今天不喝我这口，往后你发达了在别处摆摊，让人白喝——这账就平了。」他硬塞给你，「路上没有白拿，只有先拿后还。你先欠着，我说这话不臊——你将来还得起。」"}}]},{xinglu:"是岁剑冢一课。老汉把话说到根上——「赠出去的东西不折本——折的是心，攒的也是心。」",text:"「我最得意的不是这一坛埋在路口的清水。」老汉朝远处一指，「是那边——你看见没有？」「贼的事后来还有下文。」老汉说，「那放柴的汉子，如今每年冬天帮我补牌换绳——他说他当年走投无路，是砸牌子那一晚看见『夜路慢行』四个字，坐在地上哭了半夜。第二天天亮他就不偷了。」老汉拍拍新牌子，「一块破木头，救了两个人——我一个，他一个。」「记住这条道的规矩。」老汉指指一坛埋在路口的清水，「用的时候想着点别人，够用的就别多拿——这不是我的规矩，是路自己的规矩。守住了，这东西就一直有。」",options:[{label:"「规矩我守住了。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"恩",text:"帮老汉记了一日赠账，见一条道的人心"},text_after:"你收下了。那包东西在行囊里放了很久，一直没舍得吃——不是舍不得，是想起老汉说的「路上有人惦记」，就觉得这世上怎么走都走不黑。后来你也学他，在自家门前挂了壶凉茶。挂上去那天你才懂：那不是茶，是把当年受的那份踏实，接着往下传。"}},{label:"「别拿这些哄我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」老汉居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一坛埋在路口的清水像一方小小的印，盖在漫长的路上。"}}]}]},adv_g164_shouye:{id:"adv_g164_shouye",title:"雪山剑院里夜里替人醒着的老汉",mother:"M2",channel:"T3",rarity:1,entry:{node:"by_jianyuan",chance:.13},stages:[{xinglu:"是岁雪山剑院逢老汉。老汉的话糙，理却直——「夜不怕黑——夜怕的是没人醒着。」",text:"夜里你到雪山剑院，老汉提着一园将熟的瓜果巡到跟前，先给你照了个亮。「守夜人最要紧的不是胆，是觉浅。」老汉笑道，「风吹草动，我在三里外的被窝里都能竖起耳朵。这不是本事——这是把心搁在雪山剑院搁了二十年，搁熟了。」「夜深了。」老汉看看天，「你歇你的。我照旧巡我的——鸡叫之前，你听不见一点动静。这是我的保票。」",options:[{label:"「夜里的事，讲讲。」",goto:1,effect:void 0},{label:"「我家的事不用你管。」",end:!0,effect:{stat:{wuxing:1},text_after:"「有病？」老汉也不恼，「我这病生了二十年，治好了几百户人的安稳觉。你说谁有病？」他把灯一提，「前头黑，跟紧——有病的人给你照路。」你跟着他走过那段黑路，一路无话。到了亮处他站住：「去吧。有病的人不送了。」你走出老远，回头看那点灯火还立在原地——你忽然觉得，有病的人，比没病的都清醒。"}}]},{xinglu:"是岁雪山剑院一课。老汉把话说到根上——「守夜这行，眼睛不能好使——太好使了，看见的事多，心里搁不下。」",text:"「守夜二十年，我就遇过一回真险。」老汉说到这儿，摸了摸一园将熟的瓜果。「那回真险，是山洪。」老汉说，「后半夜我听见上游水声不对——平年这时候是涓涓的，那晚是闷雷似的。我挨家砸门，砸了四十七扇。水进村的时候，人都站到坡上了。第二天清点，一只鸡都没少。后来官府来查，问谁先发现的——我说没人发现，水自己来的。他们信了。我为什么不说？说了，下回还得我去砸门——我乐意砸，可功劳这东西，一人占了，别人就不干了。」「你走吧，天亮了路好走。」老汉收了灯，「夜里的事你记着一半就行——另一半，是留给夜里的人的。」",options:[{label:"「这一夜，谢过了。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"恩",text:"受老汉夜路相送一程，雪山剑院三里无事故"},text_after:"天亮了。你按老汉教的走了那条新路——果然避开了塌方段。回头望，老汉已经收了灯，正往回走。他的背影在晨光里瘦得像根梆子，可你觉得，这一夜雪山剑院的太平，全是这根梆子敲出来的。"}},{label:"「夜里太平是运气，不是你的功。」",end:!0,effect:{stat:{wuxing:1},text_after:"「我照不了多远，是真的。」老汉看着手里的灯，居然认了，「可我熄了，还有下一盏——我挑的徒弟，正学着觉浅呢。灯照不了多远不要紧，要紧的是一直亮着。你要赶路就赶吧——」他让开道，「前头三里没灯。你走的时候，替我记着这三里的黑。哪天你点上什么，别忘了我这话。」"}}]}]},adv_g165_shiyi:{id:"adv_g165_shiyi",title:"天阶遗址里替失物寻主人的老妇",mother:"M6",channel:"T1",rarity:1,entry:{node:"kx_tianjie",chance:.08},stages:[{xinglu:"是岁天阶遗址逢老妇。老妇的话糙，理却直——「世上的失物比失物的人多——总得有人替它们排队等主人。」",text:"老妇在天阶遗址整理一筐孩子丢在路边的玩物，一件一件编号，比账房先生还仔细。「我这行有个规矩：不卖。」老妇说，「有人出大价钱买一筐孩子丢在路边的玩物里的好货，我不卖。卖了这行就脏了——往后人家丢了东西，第一反应不是来找我，是猜我。」老妇递给你一件失物：「你摸摸。摸完了你说说，它的主人是个什么样的人？」",options:[{label:"「我帮你认认。」",goto:1,effect:void 0},{label:"「失物还想着领？痴人。」",end:!0,effect:{stat:{wuxing:1},text_after:"「破烂？」老妇也不恼，随手拿起一件，「这顶帽子，里面绣着一个『安』字——是个当娘的给儿子缝的。儿子当兵走了，帽子落在渡口。你说这是破烂——那这位当娘的，这三年托人问了七个州府，问的是什么？」他把帽子轻轻放回去，「破烂是没名字的东西。这儿的东西，个个有名字，只是暂时没人喊。」你出门时回头看了一眼——满屋子的东西在灯影里静着，忽然都不像破烂了。"}}]},{xinglu:"是岁天阶遗址一课。老妇把话说到根上——「每件遗物背后都站着一个着急的人——我急他所急。」",text:"「拾遗这行，也有发懵的时候。」老妇说，「讲一件，你听听值不值。」「发懵的事是这样的：有个妇人丢了亡夫的一枚章，在我这儿登了记，急得三天没吃。」老妇说，「两年后东西寻着了，送上门——她看着章，忽然平静得很，说了声『原来在这』，就收下了，连谢都没谢。」老妇苦笑，「我懵了半个月。后来懂了：她这两年，是把人一点一点放下了。章送到了，她哀也尽了。我这一行，有时候送到的是东西，有时候送到的——是结局。」「东西你拿走一件。」老妇忽然说，「不是送你——是托你。你走到别处，替它问问它的主人。我守在这儿出不去，你的腿比我的长。」",options:[{label:"「您守的不是破烂。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"恩",text:"听老妇讲半只风筝的旧事，识得失物的轻重"},text_after:"你帮着把那箱旧信按笔迹归了类——竟分出七户不同的人家。老妇眼睛都亮了：「七年了，头一回有人帮我拆这个死结。这七户人家，我挨家去送——送完一户，我就少守一件。」他非要塞给你一枚旧铜钱作谢：「失物账上添你一笔——这行的规矩，帮过忙的，都是祖师爷的人。」"}},{label:"「替人守物，自己吃什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「吃什么？」老妇指指墙角的一张木床、一只小灶，「我就住这儿。失物招领不收钱——我另有营生，替各家修修补补，饿不死。」他嘿嘿一笑，「你问的不是这个吧？你是问我图什么。图什么——图我娘。我娘丢了她的陪嫁镯子，急疯了。有人替她寻回来了。那年我十岁，站在门口看那个人把镯子递给我娘——我娘笑了。我这辈子，就想当那个人。」"}}]}]},adv_g166_wenlu:{id:"adv_g166_wenlu",title:"玉虚宫残殿的一课：少年只问不答",mother:"M7",channel:"T2",rarity:2,entry:{node:"kx_yuxu",chance:.08},stages:[{xinglu:"是岁玉虚宫残殿逢少年。少年的话糙，理却直——「人这一生，答案会过期——问题不会。」",text:"你被少年叫住：「别急着走。你说——人为什么要问路？」「我这一册写满问句的手记上挂满了问句。」少年指给你看，「有客人替我答的，有我自己想了三十年的。挂在这儿——路过的人看一眼，想一会儿，这一会儿，就值。」少年看着你：「客人，我问你——你这一路，是奔着什么来的？别急着答，想清楚再说。」",options:[{label:"「我想清楚再答。」",goto:1,effect:void 0},{label:"「怪人一个，不理也罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「怪人就怪人。」少年笑呵呵的，「玉虚宫残殿人人都这么叫。可你也看见了——他们路过还是要看一眼我那牌子。为什么？怪话里头，偶尔藏着正经。人不能全信怪人，可也不能一个怪人都不信——全信了傻，全不信了苦。你自己掂量。」他冲你摆摆手，继续挂他的问题。"}}]},{xinglu:"是岁玉虚宫残殿一课。少年把话说到根上——「答是别人的，问才是自己的——会问的人，走哪儿都带着老师。」",text:"「有个问题，我自己答不上来。」少年望着一册写满问句的手记，「挂了三十年。今天说给你听听。」「救过人的那个问题，是这样：」少年说，「有个后生来问路，话里话外透着不想活。我没劝——劝是最没用的。我就问他：你打算把这一身本事还给谁？他愣了。我说，你娘把你养这么大，你这一手好木匠活，是跟她学的还是自己学的？他哭了。哭完回去接着做木匠。后来他徒弟满天下——你说我那个问题值多少钱？」少年摆摆手，「不值钱。可它会勾人——勾着勾着，人就把自己勾回来了。」「客人慢走。」少年拱手，「你今天答了我好几个问题——答得对不对不要紧，你认真想了。认真想的人，走哪儿都带着先生。这先生就是你自己的那颗心——别偷懒使唤它。」",options:[{label:"「这问题，我收下了。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"恩",text:"从少年的墙里摘走一个问句，一年后连本带利还了"},text_after:"「看，还是觉得——这一句你带走了。」少年满意地送你出门。后来你在生意上、恩怨里、抉择前，无数次问自己这一句。它不能替你做对的事——可它让你少做了许多自以为对的事。你从此逢人便传这句话，传的时候都说是从一个怪老头那儿听来的。"}},{label:"「答案拿来，问题免了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不顶饭吃？」少年不急不恼，「饭是吃的，问题是活的。光吃饭不想事的人，跟牲口拉磨一个样——磨转得再快，路一寸没走。我不是笑话你——我五十岁之前也是这么活的。」他拍拍一册写满问句的手记，「后来才明白：问，是人跟牲口隔的那一道。」"}}]}]},adv_g167_jizhang:{id:"adv_g167_jizhang",title:"路遇清瘦老者——在蜀山山门替人情记着账",mother:"M8",channel:"T3",rarity:1,entry:{node:"ss_shanmen",chance:.11},stages:[{xinglu:"是岁蜀山山门逢清瘦老者。清瘦老者的话糙，理却直——「记账人手上要清，心上要热——光清不热，是阎王；光热不清，是糊涂虫。」",text:"你到蜀山山门时，两个人正拉扯着找清瘦老者评理——清瘦老者翻开账本，一句话就断了案。「我这柜里也有死账。」清瘦老者翻开一册，「欠账的人没了，绝了户。这账我不销——我把它抄出来，年年清明在庙前念一遍。不为讨——为的是告诉街坊：这个人来过，欠过，也被人欠过。没了户，不能连名都没了。」清瘦老者打量你一番：「客人面生——有没有旧账落在我这儿？有的话，报个名姓，我一翻便知。」",options:[{label:"「我誊这页。」",goto:1,effect:void 0},{label:"「人情账，记它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「闲事？」清瘦老者笑了，「张家的牛吃了李家的苗，是闲事；王家的娃读了书没人束脩，是闲事；你小时候发高热，邻家婶子背你走过三条街——也是闲事。这世上的情分，全是『闲事』堆出来的。我记的就是这些——你说的正事，反倒用不着我记。」"}}]},{xinglu:"是岁蜀山山门一课。清瘦老者把话说到根上——「我这账本不是讨债的——是替人把「该记得」留住。」",text:"「有一笔账，记错了。」清瘦老者说这话时，手都在抖——那是最早以前的事了。「师父考我的是：背错一笔账给我听。」清瘦老者说，「我背了，背得一丝不差。他摇头说：你背的是字。他要的是我记错一笔——然后自己心疼。他说，不心疼账的记账人，记的是死数；心疼账的，记的才是人情。」清瘦老者摩挲着账本，「我后来真记错过一回——心疼得半宿睡不着。从那晚起，我才算入了行。」清瘦老者把茶续满：「别急着走。听账人的道理，不在账上——在你听完以后，回头看你自家那本账。人人心里都有一本，只是没人替你誊清。」",options:[{label:"「这碗茶，敬记账人。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"义",text:"在蜀山山门受清瘦老者一句账理：欠的记着，还的记着"},text_after:"你回头看自家那本账——还真翻出几笔糊的：有一年落难时接过的十文钱，有一个至今没谢过的人。你起身告辞，去把这十文钱的账清了。清完你忽然懂了清瘦老者的话：账不是冰的——它热在你还它的那一刻。"}},{label:"「死账就销了罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「白记？」清瘦老者居然点头，「你说得对——十笔情账，有三笔是白记的。可剩下七笔呢？」他翻开册子给我看密密麻麻的还账记录，「人情是靠不住——可总得有人头一个信。我信了三十年，换回这七本册子的『还』字。你赌人不靠得住，你赌输了也就输了；我赌人靠得住，我赢得一街的太平。这笔账，你自己算。」"}}]}]},adv_g168_shouwu:{id:"adv_g168_shouwu",title:"路遇婆婆——在剑阁守着一件旧物",mother:"M5",channel:"T1",rarity:2,entry:{node:"ss_jianzheng",chance:.12},stages:[{xinglu:"是岁剑阁逢婆婆。婆婆的话糙，理却直——「我不守物——我守的是「还有人记得」这四个字。」",text:"婆婆见了你，头一句就是：「别嫌它旧。」说的是一杆褪色的大旗。「它不是我的，是大家的。」婆婆摆摆手，「我就是替大家看着。你今天看它一眼，你也算半个守的。」婆婆直起腰看着你：「客人，你信不信——东西也挑人。它今天让你站住了脚，说明它认你。」",options:[{label:"「它的来历，讲讲。」",goto:1,effect:void 0},{label:"不搭话，绕着走",end:!0,effect:{stat:{wuxing:1},text_after:"婆婆也没恼，只是摆摆手：「不守也对。守物这行，本来就挑人——不挑出个肯停脚的，守也守不住。」你走出去老远，回头一看，他还在擦。你忽然觉得，这世上的道理，一半在书里，一半在这样的人手里。"}}]},{xinglu:"是岁剑阁一课。婆婆把话说到根上——「物不会说话，可物记得每一个守过它的人。」",text:"「有年发大水，」婆婆望着一杆褪色的大旗，「别人都撤了，我守着它没走。」「我算过账。」婆婆扳着指头，「守它这些年，花的钱、挨的骂、误的工——全是赔的。可谁家孩子路过这儿喊一声『这东西还在啊』——这一声，全赚回来了。」婆婆朝一杆褪色的大旗作了个揖，转身又朝你作了个揖：「一个替它，一个替它谢你。往后不管你走多远——记得这世上还有人在守着点什么东西，你心里就有底。」",options:[{label:"「这话我记一辈子。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"恩",text:"帮婆婆修缮一杆褪色的大旗，剑阁的旧物得以长存"},text_after:"你帮着擦完了。手上的灰蹭了一袖子，心里却出奇地熨帖。婆婆看着擦亮的一杆褪色的大旗，半天说了句：「行了，今天这一遍，值。」你走出很远才咂摸出味儿来——他谢的不是你，是它今天又被人认真对待了一回。"}},{label:"「天下旧物多了，管不过来。」",end:!0,effect:{stat:{wuxing:1},text_after:"「管不过来是实话。」婆婆点头，「可你今天站在它跟前这么久——它就多认得一个人。一个一个攒，攒着攒着，就有人管了。」"}}]}]},adv_g169_chuanyi:{id:"adv_g169_chuanyi",title:"蓬莱渡口的一课：老妇把手艺往下传",mother:"M3",channel:"T2",rarity:2,entry:{node:"pl_dukou",chance:.08},stages:[{xinglu:"是岁蓬莱渡口逢老妇。老妇的话糙，理却直——「最好的传法不是教——是让他看你做了三十年。」",text:"老妇正用一台吱呀作响的老纺车示范，做坏了，当着徒弟的面拆了重来：「错不藏——藏了错，就传了错。」老妇说这行最金贵的不是手艺，是规矩：「什么料配什么工、什么活收什么价——规矩乱了，手艺就散了。」老妇问你：「我这手艺，在外行人眼里是个什么分量？说实话，我不恼。」",options:[{label:"「为什么是这个形？」",goto:1,effect:void 0},{label:"「学这个能挣几个钱？」",end:!0,effect:{stat:{wuxing:1},text_after:"「过时了？」老妇不急不恼，「老规矩过不过时，不看年头，看它护不护人。你哪天吃了没规矩的亏，自然会想起今天这话。」你嘴上应着，心里不服。三年后你真吃了那亏——想起这话时，人在异乡，败得一塌糊涂。"}}]},{xinglu:"是岁蓬莱渡口一课。老妇把话说到根上——「手艺不认血缘，只认肯下苦功的人。」",text:"「手艺里最难的，不是教会的，是教不会的。」老妇看着你，「你听我讲讲教不会的那部分。」「成器的那个，如今在外头独当一面；走了样的那三个，拿了手艺去糊弄人。」老妇说，「我记牢的是骂我最狠的那个——他嫌我严，走了。前年他回来磕头，说在外头吃了不懂规矩的亏。我没怪他——他这一圈弯路，就是他没听完的课。」「我这一台吱呀作响的老纺车，早晚传给肯下苦功的人。」老妇望着作坊，「也许是我徒弟，也许是徒弟的徒弟，也许——是个今天来歇脚的路人。缘分这东西说不准。」",options:[{label:"「这句话，我带走了。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"义",text:"看老妇带徒一下午，学会「骂是疼」的道理"},text_after:"你对完那册子，指出两处错字。老妇当即改了，改完郑重其事地给你作了个揖：「手艺传得走不走样，就差这一个字两个字。你今天替这门手艺把住了关——往后它传到哪儿，都有你一份。」"}},{label:"「道理谁都会讲。」",end:!0,effect:{stat:{wuxing:1},text_after:"「道理是会讲。」老妇不恼，「可我讲了三十年，徒弟们信了——你嘴上不信，眼睛信了。你进来到现在，眼睛没离开过它三回。」你哑口无言。他笑着送你出门：「不信没关系，手艺等得起。它等你一辈子，我都等得起。」"}}]}]},adv_g170_haiyuan:{id:"adv_g170_haiyuan",title:"仙市里替故人还愿的老妇",mother:"M4",channel:"T3",rarity:1,entry:{node:"pl_xianshi",chance:.06},stages:[{xinglu:"是岁仙市逢老妇。老妇的话糙，理却直——「一个愿就是一条路，替人走路的，自己也有路走。」",text:"仙市里，老妇捧着一支没吹完的曲子出神——你一问，他说这是故人留下的。「他走的时候，就念叨这一件事。」老妇拍拍一支没吹完的曲子，「人在病床上，话都说不全了，就这事翻来覆去。我当时应了——应了就得办，办不完，我闭不上眼。」「帮我看看这字还认得出么？」老妇展开一页旧纸，「水渍沤了一角——这可是他的亲笔，少一个字，愿就缺一角。」",options:[{label:"「愿闻其详。」",goto:1,effect:void 0},{label:"「人都没了，何必呢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「路远事烦？」老妇笑了，「路是死的，事是活的。你嫌烦的事，兴许正是别人临终攥着的念想。我不怪你——年轻时我也这么想。就当我今天这些话，是说给二十岁的我听的。」你脸上一热，他已转身走远。"}}]},{xinglu:"是岁仙市一课。老妇把话说到根上——「心愿这东西，拖一天就淡一天——淡到最后就真的没了。」",text:"「有人劝我把一支没吹完的曲子放到庙里，让菩萨替我管。」老妇摇头，「你听听我为什么不肯。」「蹊跷事是这样的：那年到地方，收信的人家早搬了。」老妇说，「我打听三个月，问遍十里八乡——就在我要走的前一天，一个后生找上门：我是他孙子，爷爷临终说，会有人送东西来。」老妇摊开手，「你说，愿认路，还是我认路？我不知道。我只知道，愿不能停在半道。」老妇重新收拾好行囊：「客人的话我记下了。愿还得接着赶路——它等不起，我也不能老。」他冲你拱手，「你若哪天也遇上该还的愿——别拖。拖，是还愿这行唯一的死敌。」",options:[{label:"「愿您一路顺遂。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"义",text:"受老妇所托记下善缘，替走了的人结一个活缘"},text_after:"你把记得的线索全说了——竟真有一条有用。老妇愣在原地，半晌，深深作了个揖：「客人，你今天替一个走了两年的人，把愿往前推了三里地。」他非要留给你一样谢礼，你说不必，他坚持：「愿上的账，不能欠。你收下——不然我这一路，就白背了心债。」"}},{label:"「这故事听着累。」",end:!0,effect:{stat:{wuxing:1},text_after:"「累？」老妇笑了，「我讲的累，是别人的命换来的道理。你嫌累，道理不怪你——可道理也不会再来找你。走吧。」你走出去半里，忽然想折回来问问他那花田的事——终究没折。那半里路，你走得比来时快，也比来时轻浮。"}}]}]},adv_g171_zengxing:{id:"adv_g171_zengxing",title:"路遇婆婆——在劫峰白送路上的东西",mother:"M1",channel:"T1",rarity:1,entry:{node:"pl_jiefeng",chance:.11},stages:[{xinglu:"是岁劫峰逢婆婆。婆婆的话糙，理却直——「路边这点东西救不了命——可有时人就差这一口。」",text:"你打劫峰过，婆婆招呼你：「歇歇脚？不要钱，也别推——推就见外了。」「有人问我图什么。」婆婆摆摆手，「图什么？我夜里从这儿过，看见路人的灯笼从我摆的东西旁边过去——那一刻我就图了。人活着，总得有点自己知道就行的事。」「你给我评评，」婆婆指着木牌，「这两个字哪个当头好——『自取』还是『共济』？我想了半年了。」",options:[{label:"「我来记这一笔。」",goto:1,effect:void 0},{label:"「我不占人便宜。」",end:!0,effect:{stat:{wuxing:1},text_after:"「收买人心？」婆婆愣了一下，随即苦笑，「我要能收买人心，先把我自己这颗买服帖——它总嫌我瞎折腾。」他把东西收回，也不恼，「客人防着点也好。可你记住：天下收买人心的，都要你报答；我什么都不要——你要是连不要报答的都不敢信，这世道可就真没救了。」他这话说得平静，你却走得脸热。"}}]},{xinglu:"是岁劫峰一课。婆婆把话说到根上——「东西有价，搭把手没价。」",text:"「有人劝我立个碑，写上善人某某。」婆婆摇头，「你听听我为什么不立。」「贼的事后来还有下文。」婆婆说，「那放柴的汉子，如今每年冬天帮我补牌换绳——他说他当年走投无路，是砸牌子那一晚看见『夜路慢行』四个字，坐在地上哭了半夜。第二天天亮他就不偷了。」婆婆拍拍新牌子，「一块破木头，救了两个人——我一个，他一个。」「记住这条道的规矩。」婆婆指指一包缝在树洞里的针线，「用的时候想着点别人，够用的就别多拿——这不是我的规矩，是路自己的规矩。守住了，这东西就一直有。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"在劫峰受婆婆一程之赠，学「路上有人惦记」的道理"},text_after:"你记住了那条规矩。后来你真在道上遇着同样的摊子，取的时候留了双份的钱压在木牌下。摊主追出来还钱，你说：「前头劫峰有位老丈教的——够用就行，多留是给后头的。」摊主愣了愣，朝你作了个揖。那一刻你忽然明白：婆婆的账本，原来一直记到你身上。"}},{label:"「世道就这样，你改变不了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「哄你？」婆婆笑了，「我哄你做什么？我又不要你的钱、不要你的命。我哄你，你就信了天下还有点好事——这买卖我亏了还是赚了？」他把东西又塞回你怀里，「拿着。信不信由你——东西是真的，渴了是真的，就这么简单。」"}}]}]},adv_g172_shouye:{id:"adv_g172_shouye",title:"在妖渊上层渔场，夜里替人醒着的盲眼老者",mother:"M2",channel:"T2",rarity:1,entry:{node:"yy_shangceng",chance:.13},stages:[{xinglu:"是岁妖渊上层渔场逢盲眼老者。盲眼老者的话糙，理却直——「夜不怕黑——夜怕的是没人醒着。」",text:"你被盲眼老者的梆子声唤醒——「三更了，无事。睡吧。」他巡过你的窗，脚步又轻又稳。「夜里我谁也不查。」盲眼老者说，「我就是走。走给睡的人听——听见脚步，贼不敢动，病人心安，失眠的知道天总会亮。我这一双脚，是妖渊上层渔场的定心丸。」「往前头去有段黑路。」盲眼老者把灯举高了些，「我送你过——反正我也要巡到那边。」",options:[{label:"「有您这句保票，我睡了。」",goto:1,effect:void 0},{label:"「半夜不睡，有病吧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不用我管？」盲眼老者收了灯，「好，我不管。可我巡到你家墙根，听见里头摔东西——我照旧多站一刻。为什么？我婆娘也摔过。摔东西的人，多半是喊救命喊不出声的。」他把灯转回去，「你家的事我不管——你的命，我夜里路过总得看一眼。」你那一夜睡得极不安稳。"}}]},{xinglu:"是岁妖渊上层渔场一课。盲眼老者把话说到根上——「守夜不图别的——图鸡叫的时候，家家还都是囫囵的。」",text:"「我这一行，最怕的是换班。」盲眼老者说，「换一次班，妖渊上层渔场就多一夜的险。你听我讲讲就明白了。」「那回真险，是山洪。」盲眼老者说，「后半夜我听见上游水声不对——平年这时候是涓涓的，那晚是闷雷似的。我挨家砸门，砸了四十七扇。水进村的时候，人都站到坡上了。第二天清点，一只鸡都没少。后来官府来查，问谁先发现的——我说没人发现，水自己来的。他们信了。我为什么不说？说了，下回还得我去砸门——我乐意砸，可功劳这东西，一人占了，别人就不干了。」「你走吧，天亮了路好走。」盲眼老者收了灯，「夜里的事你记着一半就行——另一半，是留给夜里的人的。」",options:[{label:"「这话我懂了。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"义",text:"听盲眼老者讲砸门四十七扇的旧事，识得守夜人的分寸"},text_after:"灯熄了，天亮了。你走出妖渊上层渔场很远，回头看不见灯，可你知道它在——就像你知道这世上有一群人，一辈子活在别人的梦里，为的是别人的梦别变成噩梦。你朝着妖渊上层渔场的方向作了个揖。天光大亮，路上人多了，谁也不知道你这一揖揖的是什么。"}},{label:"「守夜能守出什么名堂。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」盲眼老者指指自己的眼睛，「我这双眼二十年没睡过一个整觉——妖渊上层渔场每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g173_shiyi:{id:"adv_g173_shiyi",title:"老人在妖域水域替失物寻主人",mother:"M6",channel:"T3",rarity:2,entry:{node:"yy_zhongceng",chance:.08},stages:[{xinglu:"是岁妖域水域逢老人。老人的话糙，理却直——「每件遗物背后都站着一个着急的人——我急他所急。」",text:"妖域水域的角落里有一间小屋，老人守着一叠无主的田契——那是他的全部营生，也是他的全部心事。「有人笑我守着一堆破烂。」老人不恼，「我说你不懂——破烂搁在你家是破烂，搁在我这儿，是有主的。只等它的主人哪天想起来。人这一辈子，谁没落下过点什么？」「你说，」老人忽然问，「东西找到主人重要，还是主人放下了重要？我想了十年，没想明白。」",options:[{label:"「搭把手，算我一个。」",goto:1,effect:void 0},{label:"「一堆破烂，守着做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「破烂？」老人也不恼，随手拿起一件，「这顶帽子，里面绣着一个『安』字——是个当娘的给儿子缝的。儿子当兵走了，帽子落在渡口。你说这是破烂——那这位当娘的，这三年托人问了七个州府，问的是什么？」他把帽子轻轻放回去，「破烂是没名字的东西。这儿的东西，个个有名字，只是暂时没人喊。」你出门时回头看了一眼——满屋子的东西在灯影里静着，忽然都不像破烂了。"}}]},{xinglu:"是岁妖域水域一课。老人把话说到根上——「东西丢了有人找，人丢了没人寻——我干的是寻人的活。」",text:"「我这里头，最贵的一件东西，」老人指指一叠无主的田契，「一文钱不值。可它等主人等了十五年。」「那件一文不值的，是半只风筝。」老人从柜里捧出来，「碎得没法再飞了。是个娃丢的——他爹重病，他放了一天风筝，说放完了爹就好了。爹没好，走了。风筝也丢了。」老人声音低下去，「我找了他四年。找到时那娃已经不哭了，只说了句：叔叔，风筝回来了，是不是爹也记得回来？我答不上来。我把风筝给他，他把他爹留的一枚旧扣子给我——说换。我没推。我库里的东西，就数这件最贵。」「东西你拿走一件。」老人忽然说，「不是送你——是托你。你走到别处，替它问问它的主人。我守在这儿出不去，你的腿比我的长。」",options:[{label:"「愿您满屋的东西早归主。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"义",text:"听老人讲半只风筝的旧事，识得失物的轻重"},text_after:"你帮着把那箱旧信按笔迹归了类——竟分出七户不同的人家。老人眼睛都亮了：「七年了，头一回有人帮我拆这个死结。这七户人家，我挨家去送——送完一户，我就少守一件。」他非要塞给你一枚旧铜钱作谢：「失物账上添你一笔——这行的规矩，帮过忙的，都是祖师爷的人。」"}},{label:"「东西丢了再买就是。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人就痴人。」老人坦然得很，「这世上总得有人痴——都精明着，丢的东西就真没了。你精明你的，我痴我的。哪天你精明不动了、累了，我这一屋子痴，兴许还能给你焐焐手。」"}}]}]},adv_g174_wenlu:{id:"adv_g174_wenlu",title:"盲眼老者在南天门只问不答",mother:"M7",channel:"T1",rarity:1,entry:{node:"xj_nantianmen",chance:.13},stages:[{xinglu:"是岁南天门逢盲眼老者。盲眼老者的话糙，理却直——「问句是钩子——鱼上不上钩不要紧，水被搅活了就行。」",text:"盲眼老者正把新写的问题挂上一只装满纸条的竹筒：「客人看看，这个问题值得挂么？」「我这一辈子没什么成就。」盲眼老者摩挲着一只装满纸条的竹筒，「就攒了一堆问题。可你别说——城东那个木匠，是回答我一个问题想通了榫卯；西街那个郎中，是回答我另一个问题改了方子。问题会跑——比答案跑得远。」「客人走南闯北，见得多。」盲眼老者凑近了些，「帮我评评，这个问题，问得蠢不蠢？」",options:[{label:"「我想清楚再答。」",goto:1,effect:void 0},{label:"「问那么多做什么，干活要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「怪人就怪人。」盲眼老者笑呵呵的，「南天门人人都这么叫。可你也看见了——他们路过还是要看一眼我那牌子。为什么？怪话里头，偶尔藏着正经。人不能全信怪人，可也不能一个怪人都不信——全信了傻，全不信了苦。你自己掂量。」他冲你摆摆手，继续挂他的问题。"}}]},{xinglu:"是岁南天门一课。盲眼老者把话说到根上——「问题挂在这儿，不急着答——有些问题本身就是灯。」",text:"「有个问题，我自己答不上来。」盲眼老者望着一只装满纸条的竹筒，「挂了三十年。今天说给你听听。」「救过人的那个问题，是这样：」盲眼老者说，「有个后生来问路，话里话外透着不想活。我没劝——劝是最没用的。我就问他：你打算把这一身本事还给谁？他愣了。我说，你娘把你养这么大，你这一手好木匠活，是跟她学的还是自己学的？他哭了。哭完回去接着做木匠。后来他徒弟满天下——你说我那个问题值多少钱？」盲眼老者摆摆手，「不值钱。可它会勾人——勾着勾着，人就把自己勾回来了。」「我这一只装满纸条的竹筒上的问题，谁都可以摘。」盲眼老者说，「摘走的记得回来还——还的不是纸条，是你自己酿的答案。利息不高，一辈子还一回就行。」",options:[{label:"「看，还是觉得——我记下了。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"义",text:"受盲眼老者所托带走一个三十年的问题"},text_after:"「先生就是你自己的心。」你出门时回头看了一眼——盲眼老者已经转回一只装满纸条的竹筒前，又在写新问题了。你忽然明白这老头为什么从不给答案：答案是他给不起的——人人的路不一样。他给的是火折子，路得你自己摸黑走。可有了火折子，摸黑也走得直。"}},{label:"「答案拿来，问题免了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」盲眼老者把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g175_jizhang:{id:"adv_g175_jizhang",title:"天庭衙署的一课：盲眼老者替人情记着账",mother:"M8",channel:"T2",rarity:1,entry:{node:"xj_yashu",chance:.08},stages:[{xinglu:"是岁天庭衙署逢盲眼老者。盲眼老者的话糙，理却直——「别人记账怕错——我记账怕漏。错了改得回来，漏了就真没了。」",text:"你到天庭衙署时，两个人正拉扯着找盲眼老者评理——盲眼老者翻开账本，一句话就断了案。「你看过穷人家怎么还账么？」盲眼老者声音柔下来，「还一只鸡蛋、帮半天工、送一把自己种的葱。搁在钱庄，这不算还。搁在我这儿，照样一笔一笔冲抵——账清了，人的腰杆就直了。」盲眼老者打量你一番：「客人面生——有没有旧账落在我这儿？有的话，报个名姓，我一翻便知。」",options:[{label:"「先记欠的。」",goto:1,effect:void 0},{label:"「我不欠谁的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「过去？」盲眼老者摇头，「过得去的才叫过去。过不去的，你不理它，它就长在心里长成疙瘩。我这柜子里的账，一半是让人过得去的——账面摆出来，多少年的疙瘩，一句话就解了。」"}}]},{xinglu:"是岁天庭衙署一课。盲眼老者把话说到根上——「我这账本不是讨债的——是替人把「该记得」留住。」",text:"「你见过两家人为一笔账断了二十年的来往么？」盲眼老者说，「我接手过。」「师父考我的是：背错一笔账给我听。」盲眼老者说，「我背了，背得一丝不差。他摇头说：你背的是字。他要的是我记错一笔——然后自己心疼。他说，不心疼账的记账人，记的是死数；心疼账的，记的才是人情。」盲眼老者摩挲着账本，「我后来真记错过一回——心疼得半宿睡不着。从那晚起，我才算入了行。」盲眼老者把茶续满：「别急着走。听账人的道理，不在账上——在你听完以后，回头看你自家那本账。人人心里都有一本，只是没人替你誊清。」",options:[{label:"「回头我看自家那本账。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"在盲眼老者账上被记了一笔：「今天有个客人，听完了整本账」"},text_after:"你回头看自家那本账——还真翻出几笔糊的：有一年落难时接过的十文钱，有一个至今没谢过的人。你起身告辞，去把这十文钱的账清了。清完你忽然懂了盲眼老者的话：账不是冰的——它热在你还它的那一刻。"}},{label:"「死账就销了罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「靠山？」盲眼老者把账本举起来，「靠山会倒，靠人会跑，靠钱会花完——靠账呢？账是死的，可它记得的事是活的。你走投无路那天，敲开一户人家的门，报上名姓，人家翻出账本：『你家当年救济过我们……』——你说这不是靠山，什么才是？我这柜子，是几千户人的老底。」"}}]}]},adv_g176_shouwu:{id:"adv_g176_shouwu",title:"瑶池来了个守着一件旧物的老妇",mother:"M5",channel:"T3",rarity:2,entry:{node:"xj_yaochi",chance:.09},stages:[{xinglu:"是岁瑶池逢老妇。老妇的话糙，理却直——「守的东西不值钱——守本身值钱。」",text:"老妇在瑶池守了一座旧烽火台，见你打量，先开口说了它的来历。「当年交给我的时候说，守到守不动为止。」老妇摩挲着一座旧烽火台，「我算了算，还早。我还能守——它也还站得住。」「你眼神正。」老妇端详你半天，「守东西这行，挑的就是眼神。你这样的，学会了走到哪儿都饿不死——心里有东西的人，饿不死。」",options:[{label:"「有什么我能搭手的？」",goto:1,effect:void 0},{label:"「东西旧了就该换。」",end:!0,effect:{stat:{wuxing:1},text_after:"「换是要换的，」老妇在你背后说，「可换下来旧的，总得有人管。都等着别人管，旧的就都成了垃圾。」你没回头，可这句话跟了你一路。"}}]},{xinglu:"是岁瑶池一课。老妇把话说到根上——「守着它，它就不是破烂；撒手了，它就是一堆废料。」",text:"「我师父守它三十年，我接了二十年。」老妇说，「加起来五十年，还没它站着的年头长。」「师父留的那句话，我琢磨了二十年。」老妇说，「他写的是：守到你觉得是它在守你，才算入门。我当时不懂——现在懂了。它站在这儿，我就不敢倒下。」老妇从怀里掏出一小截红绳系在一座旧烽火台上：「系上它，往后你就是半个守物人。规矩不用你背——见了它脏了，你心里过意不去，就够格了。」",options:[{label:"「往后路过，我来看它。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"义",text:"帮老妇修缮一座旧烽火台，瑶池的旧物得以长存"},text_after:"你帮着查出了两处毛病——一处是底座松了，一处是渗水。老妇当场就修，修完冲你抱拳：「你这一眼，顶它多站十年。」你摆手说客气了，他正色道：「不是客气。守物人最大的难处是看不出毛病——你看出来了，就是它的造化。」"}},{label:"「这话太重，我不敢当。」",end:!0,effect:{stat:{wuxing:1},text_after:"老妇也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g177_chuanyi:{id:"adv_g177_chuanyi",title:"魔渊里把手艺往下传的老人",mother:"M3",channel:"T1",rarity:1,entry:{node:"xj_moyuan",chance:.08},stages:[{xinglu:"是岁魔渊逢老人。老人的话糙，理却直——「手艺不认血缘，只认肯下苦功的人。」",text:"魔渊里最齐整的就是一杆磨得发亮的老秤——老人说，家伙什齐整，手艺才齐整。老人教你认一杆磨得发亮的老秤的门道：「你看这儿，磨了三十年才有的包浆。手艺也一样——急不来的东西，才立得住。」「你想不想知道这一杆磨得发亮的老秤为什么是这个形？」老人卖了个关子，「知道了你就明白一半了。」",options:[{label:"「说实话——这是真功夫。」",goto:1,effect:void 0},{label:"「这些老规矩，过时了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「问挣钱？」老人放下一杆磨得发亮的老秤，「问这话的，十个里十个学不成。挣钱的手艺满街都是，可饿不死人的行当里，站得住的从来不是钱——是牌子。牌子怎么来的？活做人正。你要只为钱，趁早干别的，别糟蹋这行。」你脸上挂不住，可他说的你没法反驳。"}}]},{xinglu:"是岁魔渊一课。老人把话说到根上——「徒弟出师那天骂你，是好事——他敢自己走了。」",text:"「我这辈子收过九个徒弟。」老人伸出手比划，「成器的三个，将就的三个，走了样的三个——你猜哪个我记最牢？」「我为什么当着徒弟面拆了重做？」老人说，「因为躲一次错，徒弟就学会藏错；认一次错，徒弟就学会认错。手艺上的毛病小，人心上的毛病大——我宁可在活上丢脸，不在人上丢魂。」「我这一杆磨得发亮的老秤，早晚传给肯下苦功的人。」老人望着作坊，「也许是我徒弟，也许是徒弟的徒弟，也许——是个今天来歇脚的路人。缘分这东西说不准。」",options:[{label:"「您的手艺，不会断。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"义",text:"看老人带徒一下午，学会「骂是疼」的道理"},text_after:"你对完那册子，指出两处错字。老人当即改了，改完郑重其事地给你作了个揖：「手艺传得走不走样，就差这一个字两个字。你今天替这门手艺把住了关——往后它传到哪儿，都有你一份。」"}},{label:"「手艺早晚要绝。」",end:!0,effect:{stat:{wuxing:1},text_after:"「道理是会讲。」老人不恼，「可我讲了三十年，徒弟们信了——你嘴上不信，眼睛信了。你进来到现在，眼睛没离开过它三回。」你哑口无言。他笑着送你出门：「不信没关系，手艺等得起。它等你一辈子，我都等得起。」"}}]}]},adv_g178_haiyuan:{id:"adv_g178_haiyuan",title:"幽冥来了个替故人还愿的盲眼老者",mother:"M4",channel:"T2",rarity:2,entry:{node:"xj_youming",chance:.1},stages:[{xinglu:"是岁幽冥逢盲眼老者。盲眼老者的话糙，理却直——「人走了，愿不能跟着走——愿得有人替他走完。」",text:"幽冥歇脚处，盲眼老者给你看了一只没送到的木匣：「我要走很远的路，就为它。」「家里人劝我，人走了就放下。」盲眼老者摇头，「放下是给活人的宽心话。可愿不是包袱——愿是路标。我把这个愿还了，往后他坟头的草，我看着都顺眼。」「帮我看看这字还认得出么？」盲眼老者展开一页旧纸，「水渍沤了一角——这可是他的亲笔，少一个字，愿就缺一角。」",options:[{label:"「这字我还认得。」",goto:1,effect:void 0},{label:"「人都没了，何必呢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何必？」盲眼老者站住了，回头看你，「你也有一天会走。你走的时候，愿没还完的滋味，你尝过才知道。我劝你一句——趁身边人都在，把该说的话说了，该办的事办了。别像我，净走夜路。」他走了，你的脚步比来时重。"}}]},{xinglu:"是岁幽冥一课。盲眼老者把话说到根上——「心愿这东西，拖一天就淡一天——淡到最后就真的没了。」",text:"盲眼老者沉默了一阵，说：「其实这个愿，我本可以早点还的。」「庙里管不着这个愿。」盲眼老者摆摆手，「菩萨收的是香火，我老婆子要的不是香火——她说想再看一眼当年我们的花田。花田早荒了。我这两万里，就是要把她撒剩的这袋花籽，撒回去。」盲眼老者顿了顿，「我不求花开——求个撒了。撒了，我就能跟她交账了。」「你要是记得今天这故事，」盲眼老者说，「往后见着满头白发的还愿人，别笑他痴。给他一碗水——他替这世上所有走了的人，捎着话呢。」",options:[{label:"「善缘我收下了。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"义",text:"受盲眼老者所托记下善缘，替走了的人结一个活缘"},text_after:"你捎了他一程。一路上他把愿的来历讲了个通透，讲完长出一口气：「背了两年，今天讲顺了——讲顺了，就快了。」到了岔路口他下车，冲你长揖：「送佛送到西，你今天送的不止是我。」"}},{label:"「快些走吧，别误了我赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「帮不上不打紧。」盲眼老者摆摆手，「别缠着我——这话就伤人了。我讨的不是你的帮，是你让一步路。让一步路，天塌不下来。」他让到道旁，先请你走。你从他身边过的时候，忽然觉得这一步，让得自己心里发虚。"}}]}]},adv_g179_zengxing:{id:"adv_g179_zengxing",title:"在轮回井，白送路上的东西的婆婆",mother:"M1",channel:"T3",rarity:1,entry:{node:"xj_lunhui",chance:.09},stages:[{xinglu:"是岁轮回井逢婆婆。婆婆的话糙，理却直——「赠出去的东西不折本——折的是心，攒的也是心。」",text:"轮回井的路边，婆婆摆着一桶拴在渡口的姜汤，来者不问，取者不问。「你仔细看我的木牌。」婆婆指给你，「写的是『自取』，不是『施与』。一字之差——拿的人心里就平了。善这个东西，得把人的脸面一起护住才算善。」「客人腿脚快，是赶远路的？」婆婆问完不等答，已经把东西包好了，「远路更要带——不是干粮，是个念想。」",options:[{label:"「『自取』好。」",goto:1,effect:void 0},{label:"「少来这套收买人心。」",end:!0,effect:{stat:{wuxing:1},text_after:"「白给的好事？」婆婆哈哈大笑，「你算算这笔账：我一年搭进去几贯钱，换来这条道上的人夜里敢走、白天敢歇——你说值几贯？好事从来都白给，只是给的人不说。」你把他的话琢磨了一路，到家门口才咂摸出味儿来。"}}]},{xinglu:"是岁轮回井一课。婆婆把话说到根上——「赠人一程，自己脚下的路也宽了一寸。」",text:"「有一年冬天，来了个贼。」婆婆说起这事，倒像说旁人。「贼的事后来还有下文。」婆婆说，「那放柴的汉子，如今每年冬天帮我补牌换绳——他说他当年走投无路，是砸牌子那一晚看见『夜路慢行』四个字，坐在地上哭了半夜。第二天天亮他就不偷了。」婆婆拍拍新牌子，「一块破木头，救了两个人——我一个，他一个。」「我老了，这摊子早晚交出去。」婆婆望着路，「交给谁？交给先坐下来的那个人。谁肯坐下来陪它过日子，它就是谁的。你哪天路过歇脚——兴许就是你。」",options:[{label:"「这摊子会一直在的。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"恩",text:"受婆婆所托，允诺传递路边的规矩"},text_after:"你收下了。那包东西在行囊里放了很久，一直没舍得吃——不是舍不得，是想起婆婆说的「路上有人惦记」，就觉得这世上怎么走都走不黑。后来你也学他，在自家门前挂了壶凉茶。挂上去那天你才懂：那不是茶，是把当年受的那份踏实，接着往下传。"}},{label:"「别拿这些哄我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不算上你。」婆婆点头，「我的账是我的。可你走在这条道上，喝过路边的井水、走过别人修的桥、睡过别人盖的亭子——这些账都跟我一样，没人跟你要过。」他拍拍一桶拴在渡口的姜汤，「不用你算我的账。哪天你想起这世道不全是黑的，就够了。」"}}]}]},adv_g180_shouye:{id:"adv_g180_shouye",title:"白发老丈在天外混沌夜里替人醒着",mother:"M2",channel:"T1",rarity:2,entry:{node:"xj_hundun",chance:.12},stages:[{xinglu:"是岁天外混沌逢白发老丈。白发老丈的话糙，理却直——「夜里的规矩比白天大——因为夜里没人看着，全凭自觉。」",text:"你夜宿天外混沌，半梦半醒间听见白发老丈的脚步声一遍遍过去——一夜没停。「夜里赶路的，十个里有三个心里揣着事。」白发老丈给你照着亮，「我不问你什么事——我就把你送到亮处。人到了亮处，事就小了一半。」「往前头去有段黑路。」白发老丈把灯举高了些，「我送你过——反正我也要巡到那边。」",options:[{label:"「劳驾送一程。」",goto:1,effect:void 0},{label:"「黑路我自己认得。」",end:!0,effect:{stat:{wuxing:1},text_after:"「认得黑路是好事。」白发老丈没拦你，「可你认得的是路——路认不认你，两说。去年有个自认得路的，掉进了拆了半截的桥坑里，躺了一夜——他不知道那坑，我知道。」他举灯照了照那个方向，「喏，就那儿。坑还在，天亮我得上报。」你没再犟，跟着他走了那条亮路。"}}]},{xinglu:"是岁天外混沌一课。白发老丈把话说到根上——「夜里的灯为什么少？因为人都在睡——总得有人替睡的人醒着。」",text:"「白天的官府管不了的，夜里都得有人管。」白发老丈说，「你猜夜里都有什么事？」「当官的那位，姓陈。」白发老丈说，「那年他赶考，盘缠被偷了，蹲在一窑点火的老窑边上哭。我陪他坐了一夜，把攒的几吊钱塞给他——我婆娘还跟我吵了一架。后来他中了，回来找我，要给我修房子。我说不用——你记住这一夜就行：往后你坐堂，遇上夜里犯的事，先问问人家为什么夜里走这条路。」白发老丈说，「他真照做了。去年他断了一桩案子——贼是贼，可贼的娘病着。他判了贼，也治了他娘的病。你说我这几吊钱，值不值？」「天快亮了。」白发老丈打了个梆，「五更，天下太平。你听——鸡都叫了。这就是守夜人的一天：什么都没发生，就是最大的事。」",options:[{label:"「这话我懂了。」",end:!0,effect:{stat:{wuxing:2},trait:{yi:1},ledger:{type:"恩",text:"受白发老丈夜路相送一程，天外混沌三里无事故"},text_after:"灯熄了，天亮了。你走出天外混沌很远，回头看不见灯，可你知道它在——就像你知道这世上有一群人，一辈子活在别人的梦里，为的是别人的梦别变成噩梦。你朝着天外混沌的方向作了个揖。天光大亮，路上人多了，谁也不知道你这一揖揖的是什么。"}},{label:"「你这灯，照不了多远。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」白发老丈指指自己的眼睛，「我这双眼二十年没睡过一个整觉——天外混沌每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g181_wenlu:{id:"adv_g181_wenlu",title:"清瘦老者在青溪村只问不答",mother:"M7",channel:"T2",rarity:1,entry:{node:"qingxi",chance:.09},stages:[{xinglu:"是岁青溪村逢清瘦老者。清瘦老者的话糙，理却直——「我不教人——我提问题，路让人自己走。」",text:"你路过青溪村，清瘦老者拦住你：「客人，问你个事——你答不上来不要紧。」「你说人为什么要问路？」清瘦老者自问自答，「因为路认生。认生的东西，你不问它，它就骗你——这是路教的，我只是转述。」「我考考你。」清瘦老者眼睛一亮，「就一个问题——答上来，我这一张折了又折的路引上的问题随你挑一个带走。」",options:[{label:"「我想清楚再答。」",goto:1,effect:void 0},{label:"「卖关子，无聊。」",end:!0,effect:{stat:{wuxing:1},text_after:"「我答？」清瘦老者摊开手，「我要是答得上，还开店做什么？」他指指一张折了又折的路引，「你看这满墙的问题——我答上的不到十个。剩下的，都是别人答的、路教的、年头给的。我这不是卖关子——我是个替人传话的，传天地的、传岁月的、传你自己心里的。你急着要我答，就像问镜子要路——路在你脚下，不在镜子里。」"}}]},{xinglu:"是岁青溪村一课。清瘦老者把话说到根上——「问不丢人——不懂装懂才丢人。」",text:"「有人骂我，说问了半天屁用没有。」清瘦老者居然点头，「他骂得对。你听听怎么回事。」「三十年挂着的那个问题是：人这一生，是答案重要，还是问得对重要？」清瘦老者缓缓道，「年轻时我赌答案是重要的——答对了就赢了。后来发现，答对的都有过期的一天。如今我改赌了：问得对重要。问对了，答错了能重来；问错了，答对了也是白答。」清瘦老者笑了笑，「你呢？你怎么赌？不用现在答——这个问题，现在也归你了。」清瘦老者把一张纸条郑重推给你：「这个问题归你了。不急——哪天想通了，丢进我这竹筒里就行，人不用来。问题认字不认人。」",options:[{label:"「利息我必还。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"义",text:"在清瘦老者店里吵了一架，各自往前挪了半步"},text_after:"你收下那个问题，揣了三年。第三年秋天你在异乡的田埂上想通了——回去时清瘦老者的店还开着，你把答案丢进竹筒。后来听说他每逢初一就摇竹筒听响，笑着说：「这条又满了。」你不知道他说的哪条是你——可你知道，有个人的问题，替你养了三年的心。"}},{label:"「答案拿来，问题免了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」清瘦老者把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g182_jizhang:{id:"adv_g182_jizhang",title:"山神庙的一课：婆婆替人情记着账",mother:"M8",channel:"T3",rarity:1,entry:{node:"poza",chance:.06},stages:[{xinglu:"是岁山神庙逢婆婆。婆婆的话糙，理却直——「我这账本不是讨债的——是替人把「该记得」留住。」",text:"山神庙里，婆婆守着一本记了几代人的情分簿，谁家有笔说不清的旧账，都来问他。「有人问我，死人欠的账记来做什么。」婆婆说，「记。儿子长大来翻账——看见他爹当年受过谁的恩、还过谁的债，他就知道自己是个什么根底。账本就是家谱，还是最老实的那一页。」「考考你。」婆婆合上账本，「两个人，一个欠一个还，你先记谁？——想想再答，这一笔记下去，就是规矩。」",options:[{label:"「头一页，讲讲。」",goto:1,effect:void 0},{label:"「旧账就让它过去。」",end:!0,effect:{stat:{wuxing:1},text_after:"「你不欠谁的——好啊。」婆婆忽然笑得眼睛弯起来，「这话我就给你记上：某年某月某日，有位客人说，他不欠谁的。这一笔怎么用呢——你哪天受了人的恩，想起这笔账，就得掂量掂量：真不欠，还是不肯欠？不肯欠的人多，不欠的少。」他冲你举举茶碗，「客人，别恼。账记上了，就等你哪天来改。」"}}]},{xinglu:"是岁山神庙一课。婆婆把话说到根上——「记仇的不算记账人——记仇的账越记越窄，我这种账越记越宽。」",text:"「有一笔账，记错了。」婆婆说这话时，手都在抖——那是最早以前的事了。「记错的那笔，是早年一个后生替他病重的爹来还账。」婆婆声音哑了，「我记成『还清』，其实差着半吊。他爹咽气前问起，还念叨着那半吊。等我发现，人已经没了，账差了，说不清了。」婆婆翻开账本给我看——那页边上有行小字：「错在我，补录于三年后，按利全还，还账人：他儿子。」——「他儿子在外头挣了三年，回来把半吊连本带利还了，还非要多还一份。我说不该多。他说：我爹没还完的账，我替他记得体面些。从那天起，我每笔记三遍。」「替我记一笔。」婆婆忽然说，「就说：今天有个过路的客人，坐下来听完了整本账。这一笔记下——你也是账里的人了。」",options:[{label:"「这句话，我带走了。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"恩",text:"听婆婆讲大饥年保账的旧事，识得一页纸的分量"},text_after:"「当得起什么。」婆婆连连摆手，「我这行，说到底是替人管着念想。念想是他们的，我只是个保管员。」可你看得出来，他说这话时腰板挺得笔直——一个一辈子被几千户人信着的人，那份挺直，是拿三十年的笔一笔一笔撑起来的。"}},{label:"「死账就销了罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「销不得。」婆婆摇头，「死账销了，你就当这人没来过。可他来过——他欠账的时候是个活人，有爹娘、有脾气、有舍不得。销账容易，抹一个人难。」他把死账那册抱在怀里，「我清明念他们名字的时候，庙里老和尚说我痴。我说你不痴不懂——被念到的名字，才算在人间留过脚印。」"}}]}]},adv_g183_shouwu:{id:"adv_g183_shouwu",title:"路遇白发老丈——在后山道守着一件旧物",mother:"M5",channel:"T1",rarity:2,entry:{node:"shanlu",chance:.1},stages:[{xinglu:"是岁后山道逢白发老丈。白发老丈的话糙，理却直——「物是死的，可你守它的年头是活的。」",text:"后山道角上，白发老丈在给一堵刻满名字的墙掸灰，一下一下，像在给它梳头。白发老丈守一堵刻满名字的墙守出了规矩：什么时辰来看、看哪几处、坏了找谁修——「规矩立下了，人换不要紧，规矩不能换。」「你眼神正。」白发老丈端详你半天，「守东西这行，挑的就是眼神。你这样的，学会了走到哪儿都饿不死——心里有东西的人，饿不死。」",options:[{label:"坐下陪白发老丈说说话",goto:1,effect:void 0},{label:"「这种闲事，与我何干。」",end:!0,effect:{stat:{wuxing:1},text_after:"你绕着走了。走出去老远，风里飘来一句话似的调子——白发老丈在给一堵刻满名字的墙哼曲儿。你忽然明白：人家守得高兴，根本不在乎你看不看。这么一想，你的脚步倒轻快了。"}}]},{xinglu:"是岁后山道一课。白发老丈把话说到根上——「东西没了可以再造，守的规矩断了就接不上。」",text:"白发老丈坐下来，给你讲了件旧事——讲完自己半天没言语。「没人懂的时候，我就跟它说话。」白发老丈笑了，「你别笑——说来说去，说着说着，懂的人就来了。比如你，今天就懂了三分。」白发老丈从怀里掏出一小截红绳系在一堵刻满名字的墙上：「系上它，往后你就是半个守物人。规矩不用你背——见了它脏了，你心里过意不去，就够格了。」",options:[{label:"「替它谢谢您。」",end:!0,effect:{stat:{wuxing:2},trait:{yi:1},ledger:{type:"义",text:"在后山道为一堵刻满名字的墙添了一笔守物账"},text_after:"你把来处和去处都念了。念完白发老丈笑得眼睛眯成一条缝：「好了，你们认识了。往后你不管走多远，它都算你认识的东西——人这辈子，认识的东西多了，心里就宽。」"}},{label:"「往后再说吧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「管不过来是实话。」白发老丈点头，「可你今天站在它跟前这么久——它就多认得一个人。一个一个攒，攒着攒着，就有人管了。」"}}]}]},adv_g184_chuanyi:{id:"adv_g184_chuanyi",title:"路遇驼背阿婆——在山壁石洞把手艺往下传",mother:"M3",channel:"T2",rarity:2,entry:{node:"shanbi_dong",chance:.07},stages:[{xinglu:"是岁山壁石洞逢驼背阿婆。驼背阿婆的话糙，理却直——「教一个成一个，是福气；教十个成两个，也是本分。」",text:"你到山壁石洞时，驼背阿婆正在用一只磨秃了毫的旧笔干活，几个学徒围着看，大气不敢出。「这一只磨秃了毫的旧笔，我师父用了二十年，我用三十年。」驼背阿婆说，「它比你我都老。手艺人跟家伙什的感情，你处久了才懂——它认你的手，你的手也认它。」「来，站我旁边看。」驼背阿婆招招手，「看一遍，顶听十遍。」",options:[{label:"「愿闻其详。」",goto:1,effect:void 0},{label:"不感兴趣，转身走",end:!0,effect:{stat:{wuxing:1},text_after:"「急事要紧，去忙吧。」驼背阿婆摆摆手，忽然又补了一句：「急事里最急的，往往是最不该急的。你路上想想这话。」你出了门越想越不是味儿——他怎么知道你心里正为一件不该急的事上火？"}}]},{xinglu:"是岁山壁石洞一课。驼背阿婆把话说到根上——「手艺不认血缘，只认肯下苦功的人。」",text:"驼背阿婆做完了活，泡了壶茶，话头就长了：「说起传艺，我有一肚子话。」「教不会的那部分，是火候。」驼背阿婆说，「差半分，药性不对、木头开裂、线走歪——这半分我说了三十年，徒弟们还是得自己烧坏三锅料才能懂。所以我改了法子：先让他们烧坏——心疼了，耳朵就开了。」驼背阿婆送你到门口：「来，我这有句话送出门的客人——艺是拿来敬的，不是拿来用的。敬它，它养你一辈子。」",options:[{label:"「谢先生一课。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"义",text:"受驼背阿婆所赠一句行话，行走江湖多了一面镜子"},text_after:"「能传多久？」驼背阿婆想了想，「看天。可我告诉你我的算法：只要还有人肯为一个细节较真——这门手艺就活着。你今天盯着我这活看了半晌，就在较真。所以今天，它又多活了一天。」"}},{label:"「手艺早晚要绝。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要绝就绝。」驼背阿婆淡淡地说，「手艺绝不绝，不看我这代人喊多响——看下代人肯不肯弯腰。我弯了三十年腰了，够了。绝了也不冤：它来的时候有人敬，走的时候有人送，全始全终。」你出门时回头看了一眼，驼背阿婆已经又坐回一只磨秃了毫的旧笔前——绝不绝的话撂在那儿，手上的活一天没停。"}}]}]},adv_g185_haiyuan:{id:"adv_g185_haiyuan",title:"路遇盲眼老者——在官道替故人还愿",mother:"M4",channel:"T3",rarity:2,entry:{node:"guandao",chance:.08},stages:[{xinglu:"是岁官道逢盲眼老者。盲眼老者的话糙，理却直——「我一辈子还不完的愿，就是我这辈子最富的家底。」",text:"你见盲眼老者对着一件没织完的衣裳自言自语，像在跟什么人回话。「这是我欠他的。」盲眼老者说，「当年他有难处，我没能帮上。如今他走了，我把他的愿当我的债——债这东西，躲一辈子，不如还一趟。」「帮我看看这字还认得出么？」盲眼老者展开一页旧纸，「水渍沤了一角——这可是他的亲笔，少一个字，愿就缺一角。」",options:[{label:"「这字我还认得。」",goto:1,effect:void 0},{label:"「故人的东西，留着何用。」",end:!0,effect:{stat:{wuxing:1},text_after:"「留着何用？」盲眼老者把一件没织完的衣裳举起来给你看，「你看它像东西吗？不像了——它是一句没说完的话。话没了，人才真的没了。」他说完自己收好，朝你拱拱手，「客人，话糙了。可这理，你早晚用得上。」"}}]},{xinglu:"是岁官道一课。盲眼老者把话说到根上——「我不怕愿多——我怕的是没人记得那些愿。」",text:"「有人劝我把一件没织完的衣裳放到庙里，让菩萨替我管。」盲眼老者摇头，「你听听我为什么不肯。」「为我老婆子还的愿，办起来最不觉得累。」盲眼老者摩挲着一件没织完的衣裳，「有人说我傻，人都没了。我说你没懂——她还哪儿都没去。她在这个愿里。我每走一里路，她就跟我走一里。等愿还完，她也就到家了。」盲眼老者说这话时眼里有泪，脸上却在笑。盲眼老者把一小撮路上的干粮分给你：「同行一程，就是有缘。这个你拿着——路上的人情，也是愿的一部分。我替故人结的善缘，多一个是一个。」",options:[{label:"「这碗水，我记着。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"恩",text:"捎盲眼老者一程，听了一个还愿人的故事"},text_after:"你捎了他一程。一路上他把愿的来历讲了个通透，讲完长出一口气：「背了两年，今天讲顺了——讲顺了，就快了。」到了岔路口他下车，冲你长揖：「送佛送到西，你今天送的不止是我。」"}},{label:"「我帮不上，别缠着我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「完了就完了？」盲眼老者站定，认真看你，「人走茶凉是世道。可我把茶端热的这些年，凉不了——你信不信？你今天说这话，是因为还没遇着走的人。遇着了，你会想起我。」他走了，那句话你揣了一路，越揣越沉。"}}]}]},adv_g186_zengxing:{id:"adv_g186_zengxing",title:"在宫门当值区，白送路上的东西的老汉",mother:"M1",channel:"T1",rarity:2,entry:{node:"gongmen",chance:.11},stages:[{xinglu:"是岁宫门当值区逢老汉。老汉的话糙，理却直——「白给的东西要正大光明地白给——藏着掖着，善就变了味。」",text:"老汉守着一盏风雨夜的引路灯打盹，木牌上的字被风雨磨得快看不清了，他还是每天来摆。「你仔细看我的木牌。」老汉指给你，「写的是『自取』，不是『施与』。一字之差——拿的人心里就平了。善这个东西，得把人的脸面一起护住才算善。」老汉把东西塞到你手里：「拿着。别谢——要谢，往后你也给别人备一份。」",options:[{label:"「您这摊子，摆了几年？」",goto:1,effect:void 0},{label:"「少来这套收买人心。」",end:!0,effect:{stat:{wuxing:1},text_after:"「白给的好事？」老汉哈哈大笑，「你算算这笔账：我一年搭进去几贯钱，换来这条道上的人夜里敢走、白天敢歇——你说值几贯？好事从来都白给，只是给的人不说。」你把他的话琢磨了一路，到家门口才咂摸出味儿来。"}}]},{xinglu:"是岁宫门当值区一课。老汉把话说到根上——「我不图报——我只求受的人往后也肯搭把手。」",text:"「我这一盏风雨夜的引路灯，起头不是给人用的。」老汉声音低了，「是我给自己备的。」「最高兴的一回，是个哑巴。」老汉说，「他拿了我半年，一句话说不了。有天他忽然比划着——旁边的货郎给我翻：他说，他往后的营生有了，是帮渡口搬货，东家管饭。说完他给我磕了个头。」老汉抹了把脸，「我拦都没拦住。我不是图这个——可这个，比什么都沉。」「我老了，这摊子早晚交出去。」老汉望着路，「交给谁？交给先坐下来的那个人。谁肯坐下来陪它过日子，它就是谁的。你哪天路过歇脚——兴许就是你。」",options:[{label:"「您这样的人，多几个才好。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"恩",text:"在宫门当值区白得一份干粮，后来也学着挂了一壶茶"},text_after:"你收下了。那包东西在行囊里放了很久，一直没舍得吃——不是舍不得，是想起老汉说的「路上有人惦记」，就觉得这世上怎么走都走不黑。后来你也学他，在自家门前挂了壶凉茶。挂上去那天你才懂：那不是茶，是把当年受的那份踏实，接着往下传。"}},{label:"「我不信这些。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」老汉居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一盏风雨夜的引路灯像一方小小的印，盖在漫长的路上。"}}]}]},adv_g187_shouye:{id:"adv_g187_shouye",title:"天机阁里夜里替人醒着的中年汉子",mother:"M2",channel:"T2",rarity:3,entry:{node:"tianjige",chance:.05},stages:[{xinglu:"是岁天机阁逢中年汉子。中年汉子的话糙，理却直——「夜里的事，白天看不见——看不见不等于没有。」",text:"中年汉子守在一盏渡口的夜航灯旁，火光把他的影子拉得很长，见你近前，先问了句：「夜里赶路，有事？」「守夜人最要紧的不是胆，是觉浅。」中年汉子笑道，「风吹草动，我在三里外的被窝里都能竖起耳朵。这不是本事——这是把心搁在天机阁搁了二十年，搁熟了。」「帮我留意件事。」中年汉子压低声音，「近来天机阁夜里多了个生面孔——不是我疑心，守夜人的疑心就是饭碗。你白天要是见着了，给我递个话。」",options:[{label:"「夜里的事，讲讲。」",goto:1,effect:void 0},{label:"「半夜不睡，有病吧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「有病？」中年汉子也不恼，「我这病生了二十年，治好了几百户人的安稳觉。你说谁有病？」他把灯一提，「前头黑，跟紧——有病的人给你照路。」你跟着他走过那段黑路，一路无话。到了亮处他站住：「去吧。有病的人不送了。」你走出老远，回头看那点灯火还立在原地——你忽然觉得，有病的人，比没病的都清醒。"}}]},{xinglu:"是岁天机阁一课。中年汉子把话说到根上——「夜里的灯为什么少？因为人都在睡——总得有人替睡的人醒着。」",text:"「守夜二十年，我就遇过一回真险。」中年汉子说到这儿，摸了摸一盏渡口的夜航灯。「那回真险，是山洪。」中年汉子说，「后半夜我听见上游水声不对——平年这时候是涓涓的，那晚是闷雷似的。我挨家砸门，砸了四十七扇。水进村的时候，人都站到坡上了。第二天清点，一只鸡都没少。后来官府来查，问谁先发现的——我说没人发现，水自己来的。他们信了。我为什么不说？说了，下回还得我去砸门——我乐意砸，可功劳这东西，一人占了，别人就不干了。」「你走吧，天亮了路好走。」中年汉子收了灯，「夜里的事你记着一半就行——另一半，是留给夜里的人的。」",options:[{label:"「天亮了，好走。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"义",text:"陪中年汉子守了半宿一盏渡口的夜航灯，学会「夜里的另一半」"},text_after:"天亮了。你按中年汉子教的走了那条新路——果然避开了塌方段。回头望，中年汉子已经收了灯，正往回走。他的背影在晨光里瘦得像根梆子，可你觉得，这一夜天机阁的太平，全是这根梆子敲出来的。"}},{label:"「别拦着我，我要赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「我照不了多远，是真的。」中年汉子看着手里的灯，居然认了，「可我熄了，还有下一盏——我挑的徒弟，正学着觉浅呢。灯照不了多远不要紧，要紧的是一直亮着。你要赶路就赶吧——」他让开道，「前头三里没灯。你走的时候，替我记着这三里的黑。哪天你点上什么，别忘了我这话。」"}}]}]},adv_g188_shiyi:{id:"adv_g188_shiyi",title:"内市里替失物寻主人的白发老丈",mother:"M6",channel:"T3",rarity:2,entry:{node:"neishi",chance:.08},stages:[{xinglu:"是岁内市逢白发老丈。白发老丈的话糙，理却直——「东西无主的时候最可怜——可怜它们连个喊它名字的人都没有。」",text:"内市里，白发老丈守着一屋一筐孩子丢在路边的玩物，见你进来，先问一句：「客人丢过什么？」「我这册子记了二十年。」白发老丈翻着一筐孩子丢在路边的玩物边的旧簿，「每件失物什么样子、哪儿捡的、像是谁丢的——都记着。册子比我的脑子靠得住。人的记忆会骗人，字不会。」「客人有闲功夫没有？」白发老丈半开玩笑，「搭把手，帮我给这箱子归归类。你归过的，我记下——算你在这行挂个号。」",options:[{label:"「我没见过，帮不上。」",goto:1,effect:void 0},{label:"「一堆破烂，守着做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「没出息。」白发老丈笑了，「对——没出息，饿不死，也发不了。可你告诉我，什么行当能让人二十年睡得着觉？我这行能。我每送回一件东西，就有一户人家少一夜的睡不着。」他拱拱手，「出息是活给别人看的，觉是自己睡的。慢走。」"}}]},{xinglu:"是岁内市一课。白发老丈把话说到根上——「丢东西的人分两种：丢得起的一笑了之，丢不起的——那种你得跑断腿。」",text:"「拾遗这行，也有发懵的时候。」白发老丈说，「讲一件，你听听值不值。」「被忘了才是真的没了。」白发老丈说，「所以我这册子上的东西，一件都不许销。人忘了，我替他记着；他哪天想起来——哪怕想起来的是十年前的一件小事——东西还在，日子就还接得上。我这行当说到底，就是给人留个『接得上』。」「天不早了。」白发老丈点起灯，「我这儿夜里也开门——丢东西的人，是不分时辰的。你慢走，路上小心别落了东西。落了也不要紧——这世上还有我这样的人。」",options:[{label:"「两句话，我记牢了。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"一眼认出包袱上的字迹，省了白发老丈三个月的腿"},text_after:"你摸着那件失物说了自己的猜测——「丢它的人手上有茧，是做粗活出身，可这物件绣工极细，是替珍视的人做的。」白发老丈怔了半天，说：「二十年，头一回有人把它说活。」他把它单独搁到一个格子里，「照你这么说，它主人家里必还有一个等它的人。我再寻十年，也值得。」"}},{label:"「失物多了，你拾得过来？」",end:!0,effect:{stat:{wuxing:1},text_after:"「拾不过来。」白发老丈坦白得很，「天下的失物，我一辈子拾不完。可我多拾一件，世上就少一件没着落的。你这话跟师父当年说的一模一样——他后来呢？他拾了一辈子。」他拿起册子，「拾不过来，就一件一件来。日子长着呢。」"}}]}]},adv_g189_wenlu:{id:"adv_g189_wenlu",title:"中年汉子在四牌楼大街只问不答",mother:"M7",channel:"T1",rarity:1,entry:{node:"chengmen_dashi",chance:.13},stages:[{xinglu:"是岁四牌楼大街逢中年汉子。中年汉子的话糙，理却直——「天下没有蠢问题，只有不肯问的人。」",text:"四牌楼大街里，中年汉子守着一盏陪他坐了半生的茶炉，面前立着块牌子：「只问不答」。「你说人为什么要问路？」中年汉子自问自答，「因为路认生。认生的东西，你不问它，它就骗你——这是路教的，我只是转述。」「留个问题给你。」中年汉子说着要往你手里塞纸条，「不白留——哪天你想通了，回来告诉一声。这店里的规矩：问题不白送，得还利息。」",options:[{label:"「您考我。」",goto:1,effect:void 0},{label:"「卖关子，无聊。」",end:!0,effect:{stat:{wuxing:1},text_after:"「无聊？」中年汉子哈哈大笑，「你这话说得对——问题是挺无聊的。答案多痛快，一刀见血。可我告诉你，一刀见血的痛快，跟一刀断命的糊涂，是同一个刀法。你嫌我无聊，就是嫌自己想事太慢——慢工出的东西，急工比不了。走吧走吧，等你哪天急不动了，自然会回来找无聊。」"}}]},{xinglu:"是岁四牌楼大街一课。中年汉子把话说到根上——「问路的人最聪明——他省下的冤枉路，就是他的学问。」",text:"「有个问题，我自己答不上来。」中年汉子望着一盏陪他坐了半生的茶炉，「挂了三十年。今天说给你听听。」「救过人的那个问题，是这样：」中年汉子说，「有个后生来问路，话里话外透着不想活。我没劝——劝是最没用的。我就问他：你打算把这一身本事还给谁？他愣了。我说，你娘把你养这么大，你这一手好木匠活，是跟她学的还是自己学的？他哭了。哭完回去接着做木匠。后来他徒弟满天下——你说我那个问题值多少钱？」中年汉子摆摆手，「不值钱。可它会勾人——勾着勾着，人就把自己勾回来了。」中年汉子把一张纸条郑重推给你：「这个问题归你了。不急——哪天想通了，丢进我这竹筒里就行，人不用来。问题认字不认人。」",options:[{label:"「这问题，我收下了。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"义",text:"在四牌楼大街答了中年汉子一问，得了他一句「认真想的人自带先生」"},text_after:"你收下那个问题，揣了三年。第三年秋天你在异乡的田埂上想通了——回去时中年汉子的店还开着，你把答案丢进竹筒。后来听说他每逢初一就摇竹筒听响，笑着说：「这条又满了。」你不知道他说的哪条是你——可你知道，有个人的问题，替你养了三年的心。"}},{label:"「故弄玄虚，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不顶饭吃？」中年汉子不急不恼，「饭是吃的，问题是活的。光吃饭不想事的人，跟牲口拉磨一个样——磨转得再快，路一寸没走。我不是笑话你——我五十岁之前也是这么活的。」他拍拍一盏陪他坐了半生的茶炉，「后来才明白：问，是人跟牲口隔的那一道。」"}}]}]},adv_g190_jizhang:{id:"adv_g190_jizhang",title:"路遇妇人——在东市替人情记着账",mother:"M8",channel:"T2",rarity:2,entry:{node:"dongshi",chance:.13},stages:[{xinglu:"是岁东市逢妇人。妇人的话糙，理却直——「账本比人活得长——我把账记清楚，情分就比人长寿。」",text:"妇人正给一户人家抄账——抄完把原册还人家，抄本自己留：「一式两份，两头作数。」「我这柜里也有死账。」妇人翻开一册，「欠账的人没了，绝了户。这账我不销——我把它抄出来，年年清明在庙前念一遍。不为讨——为的是告诉街坊：这个人来过，欠过，也被人欠过。没了户，不能连名都没了。」「你识字吧？」妇人把笔递过来，「帮我誊一页。誊账有个讲究——字要端正，心要放平。你试试。」",options:[{label:"「头一页，讲讲。」",goto:1,effect:void 0},{label:"「你这行当，多管闲事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「你不欠谁的——好啊。」妇人忽然笑得眼睛弯起来，「这话我就给你记上：某年某月某日，有位客人说，他不欠谁的。这一笔怎么用呢——你哪天受了人的恩，想起这笔账，就得掂量掂量：真不欠，还是不肯欠？不肯欠的人多，不欠的少。」他冲你举举茶碗，「客人，别恼。账记上了，就等你哪天来改。」"}}]},{xinglu:"是岁东市一课。妇人把话说到根上——「记仇的不算记账人——记仇的账越记越窄，我这种账越记越宽。」",text:"「有一笔账，记错了。」妇人说这话时，手都在抖——那是最早以前的事了。「最恨我的是人贩子。」妇人冷冷道，「他们拐走的孩子，我账上都有底——哪家孩子哪年生、什么胎记、谁抱走的。他们烧过我的铺子，砍过我的门。可账在人心里的那份，他们烧不掉——街上人人替我记着。」妇人把柜子锁好，「我这账本为什么比官府的册子灵？因为官府的册子锁在库里，我的账——长在几千户人的嘴里。」「我这行干到死。」妇人说，「死了我这账传给徒弟——徒弟再传徒弟。账本不怕旧，就怕断。你哪天路过，看看它还开着门不——开着，就说明有人接着记呢。」",options:[{label:"「把我记上。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"义",text:"帮妇人誊账一页，字正心平，得了保管员三分真传"},text_after:"你回头看自家那本账——还真翻出几笔糊的：有一年落难时接过的十文钱，有一个至今没谢过的人。你起身告辞，去把这十文钱的账清了。清完你忽然懂了妇人的话：账不是冰的——它热在你还它的那一刻。"}},{label:"「账本又不是靠山。」",end:!0,effect:{stat:{wuxing:1},text_after:"「靠山？」妇人把账本举起来，「靠山会倒，靠人会跑，靠钱会花完——靠账呢？账是死的，可它记得的事是活的。你走投无路那天，敲开一户人家的门，报上名姓，人家翻出账本：『你家当年救济过我们……』——你说这不是靠山，什么才是？我这柜子，是几千户人的老底。」"}}]}]},adv_g191_shouwu:{id:"adv_g191_shouwu",title:"漕运码头来了个守着一件旧物的中年汉子",mother:"M5",channel:"T3",rarity:1,entry:{node:"matou",chance:.07},stages:[{xinglu:"是岁漕运码头逢中年汉子。中年汉子的话糙，理却直——「守的东西不值钱——守本身值钱。」",text:"漕运码头的角落里，中年汉子守着一杆褪色的大旗，守得像守着一户人家。「有人问这破玩意儿有啥可守的。」中年汉子笑了，「我说，你家里老人的旧物，你说有啥可留的？一个理——念想这东西，不作价。」「你要是赶路，就歇口气再走。」中年汉子指指旁边，「你歇的这会儿，它也算没白站着。」",options:[{label:"「有什么我能搭手的？」",goto:1,effect:void 0},{label:"「我有正事，赶路要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「赶路要紧，是正经话。」中年汉子点头，「可我告诉你——路走完了，能想起来的，往往不是路上多快，是谁让你停了一脚。你走吧，我不拦。」你走出半里地，脚步不自觉慢了下来。"}}]},{xinglu:"是岁漕运码头一课。中年汉子把话说到根上——「东西旧了不怕，怕的是没人认它。」",text:"中年汉子坐下来，给你讲了件旧事——讲完自己半天没言语。中年汉子展开那件旧物，上面是一行字：「物在人守，人在物传。」——上一任守物人给他的话，如今他念给你听。「往后你路过，来看它一眼。」中年汉子说，「不用你守——看一眼，它就多活一天。这买卖便宜吧？」",options:[{label:"「替它谢谢您。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"恩",text:"在漕运码头听中年汉子讲守一杆褪色的大旗的道理，助守一日"},text_after:"中年汉子把红绳塞进你手里：「拿着。不是定礼——是念想。往后你在别处见着没人管的东西，手痒了，就想起这截绳。」后来你还真遇着过——一处塌了半边的旧亭子，你出钱请人修了。修完你自己都笑：这算什么，守物人的瘾。"}},{label:"「这话太重，我不敢当。」",end:!0,effect:{stat:{wuxing:1},text_after:"「管不过来是实话。」中年汉子点头，「可你今天站在它跟前这么久——它就多认得一个人。一个一个攒，攒着攒着，就有人管了。」"}}]}]},adv_g192_chuanyi:{id:"adv_g192_chuanyi",title:"武行镖局街来了个把手艺往下传的白发老丈",mother:"M3",channel:"T1",rarity:1,entry:{node:"wuhangjie",chance:.13},stages:[{xinglu:"是岁武行镖局街逢白发老丈。白发老丈的话糙，理却直——「传艺先传心，心不正，手艺就是凶器。」",text:"白发老丈做完工，把一台吱呀作响的老纺车擦得锃亮——那架势像在擦一件传家宝。「我教徒弟，头一年不让碰一台吱呀作响的老纺车。」白发老丈笑，「先看、先磨性子。心浮的人拿家伙什，糟蹋东西，也糟蹋自己。」「来，站我旁边看。」白发老丈招招手，「看一遍，顶听十遍。」",options:[{label:"「为什么是这个形？」",goto:1,effect:void 0},{label:"「学这个能挣几个钱？」",end:!0,effect:{stat:{wuxing:1},text_after:"「问挣钱？」白发老丈放下一台吱呀作响的老纺车，「问这话的，十个里十个学不成。挣钱的手艺满街都是，可饿不死人的行当里，站得住的从来不是钱——是牌子。牌子怎么来的？活做人正。你要只为钱，趁早干别的，别糟蹋这行。」你脸上挂不住，可他说的你没法反驳。"}}]},{xinglu:"是岁武行镖局街一课。白发老丈把话说到根上——「我把一辈子拆成手艺，你拿去接着活。」",text:"白发老丈指指墙上挂的一幅旧字：「我师父写的。我挂了三十年，今天念给你听。」「师父那幅字写的是：手稳不如心稳。」白发老丈望着墙，「我年轻时觉得这话虚。有一年赶工，我心里乱，手没抖，活却全歪了——那一刻我才懂：手是心的影子。从那天起，我教徒弟先教静心。」「你要是也有一门营生，」白发老丈说，「记得往远处传。不一定要收徒——你把活做正了，看着的人自然学。」",options:[{label:"「谢先生一课。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"义",text:"受白发老丈所赠一句行话，行走江湖多了一面镜子"},text_after:"你站了一下午，看白发老丈带徒弟。收工时他问你看出什么没有。你说：「您骂人的话，跟夸人的话一样多。」他大笑：「对喽！手艺人捧徒弟，是害他；骂徒弟，是疼他。你往后再带人，记住这个理。」"}},{label:"「与我何干，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「道理是会讲。」白发老丈不恼，「可我讲了三十年，徒弟们信了——你嘴上不信，眼睛信了。你进来到现在，眼睛没离开过它三回。」你哑口无言。他笑着送你出门：「不信没关系，手艺等得起。它等你一辈子，我都等得起。」"}}]}]},adv_g193_haiyuan:{id:"adv_g193_haiyuan",title:"白发老丈在四牌楼贫民坊替故人还愿",mother:"M4",channel:"T2",rarity:2,entry:{node:"sipailou",chance:.1},stages:[{xinglu:"是岁四牌楼贫民坊逢白发老丈。白发老丈的话糙，理却直——「我一辈子还不完的愿，就是我这辈子最富的家底。」",text:"白发老丈在四牌楼贫民坊打听路，手里攥着一份没还清的人情——他在替谁了却一桩心愿。「我跟他打了一辈子交道，就欠这一件。」白发老丈把一份没还清的人情翻过来给你看，「你看这磨痕——都是他亲手磨的。他磨的时候念的什么，我大概知道。所以这愿，我认。」「帮我看看这字还认得出么？」白发老丈展开一页旧纸，「水渍沤了一角——这可是他的亲笔，少一个字，愿就缺一角。」",options:[{label:"「帮您辨认这页纸。」",goto:1,effect:void 0},{label:"「故人的东西，留着何用。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何必？」白发老丈站住了，回头看你，「你也有一天会走。你走的时候，愿没还完的滋味，你尝过才知道。我劝你一句——趁身边人都在，把该说的话说了，该办的事办了。别像我，净走夜路。」他走了，你的脚步比来时重。"}}]},{xinglu:"是岁四牌楼贫民坊一课。白发老丈把话说到根上——「还愿的人不问值不值——问值不值的时候，愿就已经不是愿了。」",text:"「我老婆子生前总念叨，」白发老丈声音软下来，「这个愿，是为她还的。」「蹊跷事是这样的：那年到地方，收信的人家早搬了。」白发老丈说，「我打听三个月，问遍十里八乡——就在我要走的前一天，一个后生找上门：我是他孙子，爷爷临终说，会有人送东西来。」白发老丈摊开手，「你说，愿认路，还是我认路？我不知道。我只知道，愿不能停在半道。」「我走了。」白发老丈背起行囊，「这愿还完，我就回家种地——把替人还愿的道理，讲给村口的娃娃们听。让他们知道：这世上有一种债，还的是心安。」",options:[{label:"「这碗水，我记着。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"恩",text:"捎白发老丈一程，听了一个还愿人的故事"},text_after:"「尽到心没尽到心，我自己知道。」白发老丈摇头，「可你说这话，我路上就不孤单了。还愿人最怕的不是路——是没人说一句『够了，可以了』。你说了一句。我记下了。」"}},{label:"「愿是虚的，人死了就完了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「帮不上不打紧。」白发老丈摆摆手，「别缠着我——这话就伤人了。我讨的不是你的帮，是你让一步路。让一步路，天塌不下来。」他让到道旁，先请你走。你从他身边过的时候，忽然觉得这一步，让得自己心里发虚。"}}]}]},adv_g194_zengxing:{id:"adv_g194_zengxing",title:"报国寺的一课：老人白送路上的东西",mother:"M1",channel:"T3",rarity:1,entry:{node:"bgs_shanmen",chance:.11},stages:[{xinglu:"是岁报国寺逢老人。老人的话糙，理却直——「赠出去的东西不折本——折的是心，攒的也是心。」",text:"老人守着一桶拴在渡口的姜汤打盹，木牌上的字被风雨磨得快看不清了，他还是每天来摆。「有人问我图什么。」老人摆摆手，「图什么？我夜里从这儿过，看见路人的灯笼从我摆的东西旁边过去——那一刻我就图了。人活着，总得有点自己知道就行的事。」「客人腿脚快，是赶远路的？」老人问完不等答，已经把东西包好了，「远路更要带——不是干粮，是个念想。」",options:[{label:"「我来记这一笔。」",goto:1,effect:void 0},{label:"「我不占人便宜。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不占便宜是好品性。」老人点头，「可我这不叫便宜——叫过路钱。你今天不喝我这口，往后你发达了在别处摆摊，让人白喝——这账就平了。」他硬塞给你，「路上没有白拿，只有先拿后还。你先欠着，我说这话不臊——你将来还得起。」"}}]},{xinglu:"是岁报国寺一课。老人把话说到根上——「我一辈子的买卖：本钱是自己出的，利息是天下人的。」",text:"「有一年冬天，来了个贼。」老人说起这事，倒像说旁人。「那年来了个贼，夜里偷我的东西不说，还砸了我的牌子。」老人说，「我第二天照样摆，牌子重写一块，添了四个字：『夜路慢行』。后来那贼又来——这回是白天，红着脸放下一捆柴，一句话没说走了。」老人呵呵地笑，「你瞧，善这东西不咬人，它泡人。泡久了，铁石心肠也软。」老人朝你挥挥手：「走吧走吧。东西拿了，话也听了——往后你也是个路上的人了。路上的人认路上的人，一眼就认得。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"恩",text:"受老人所托，允诺传递路边的规矩"},text_after:"你记住了那条规矩。后来你真在道上遇着同样的摊子，取的时候留了双份的钱压在木牌下。摊主追出来还钱，你说：「前头报国寺有位老丈教的——够用就行，多留是给后头的。」摊主愣了愣，朝你作了个揖。那一刻你忽然明白：老人的账本，原来一直记到你身上。"}},{label:"「世道就这样，你改变不了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」老人居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一桶拴在渡口的姜汤像一方小小的印，盖在漫长的路上。"}}]}]},adv_g195_shouye:{id:"adv_g195_shouye",title:"鬼市入口来了个夜里替人醒着的婆婆",mother:"M2",channel:"T1",rarity:1,entry:{node:"guishi_ru",chance:.06},stages:[{xinglu:"是岁鬼市入口逢婆婆。婆婆的话糙，理却直——「夜里的灯为什么少？因为人都在睡——总得有人替睡的人醒着。」",text:"你夜宿鬼市入口，半梦半醒间听见婆婆的脚步声一遍遍过去——一夜没停。「我这一段堤坝的巡查路守了二十年。」婆婆敲了敲它，「二十年，鬼市入口没出过一桩夜里的大事。人家说是这片太平——我知道不是。是夜夜有人走着。」「夜深了。」婆婆看看天，「你歇你的。我照旧巡我的——鸡叫之前，你听不见一点动静。这是我的保票。」",options:[{label:"「陪您走一段。」",goto:1,effect:void 0},{label:"「黑路我自己认得。」",end:!0,effect:{stat:{wuxing:1},text_after:"「有病？」婆婆也不恼，「我这病生了二十年，治好了几百户人的安稳觉。你说谁有病？」他把灯一提，「前头黑，跟紧——有病的人给你照路。」你跟着他走过那段黑路，一路无话。到了亮处他站住：「去吧。有病的人不送了。」你走出老远，回头看那点灯火还立在原地——你忽然觉得，有病的人，比没病的都清醒。"}}]},{xinglu:"是岁鬼市入口一课。婆婆把话说到根上——「守夜不图别的——图鸡叫的时候，家家还都是囫囵的。」",text:"「白天的官府管不了的，夜里都得有人管。」婆婆说，「你猜夜里都有什么事？」「当官的那位，姓陈。」婆婆说，「那年他赶考，盘缠被偷了，蹲在一段堤坝的巡查路边上哭。我陪他坐了一夜，把攒的几吊钱塞给他——我婆娘还跟我吵了一架。后来他中了，回来找我，要给我修房子。我说不用——你记住这一夜就行：往后你坐堂，遇上夜里犯的事，先问问人家为什么夜里走这条路。」婆婆说，「他真照做了。去年他断了一桩案子——贼是贼，可贼的娘病着。他判了贼，也治了他娘的病。你说我这几吊钱，值不值？」「天快亮了。」婆婆打了个梆，「五更，天下太平。你听——鸡都叫了。这就是守夜人的一天：什么都没发生，就是最大的事。」",options:[{label:"「这话我懂了。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"义",text:"听婆婆讲砸门四十七扇的旧事，识得守夜人的分寸"},text_after:"「心里有夜的人。」你把这句话带了很多年。后来你做了点小营生，雇伙计先看人睡觉——都笑你怪。你想起婆婆，也不解释。守夜人的道理，本来就是说给夜里的人听的。"}},{label:"「守夜能守出什么名堂。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」婆婆指指自己的眼睛，「我这双眼二十年没睡过一个整觉——鬼市入口每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g196_shiyi:{id:"adv_g196_shiyi",title:"路遇老人——在鬼市替失物寻主人",mother:"M6",channel:"T2",rarity:1,entry:{node:"guishi",chance:.07},stages:[{xinglu:"是岁鬼市逢老人。老人的话糙，理却直——「失物认人——你替它找到主人，它比你还高兴。」",text:"鬼市里，老人守着一屋一摞当铺里过期的死当，见你进来，先问一句：「客人丢过什么？」「有人笑我守着一堆破烂。」老人不恼，「我说你不懂——破烂搁在你家是破烂，搁在我这儿，是有主的。只等它的主人哪天想起来。人这一辈子，谁没落下过点什么？」「你眼神好。」老人招手，「帮我认认——这个包袱上的字，是哪府的写法？」",options:[{label:"「它像是个念旧的人丢的。」",goto:1,effect:void 0},{label:"「失物还想着领？痴人。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人？」老人摇头，「你丢了东西就知道了——丢东西的人，个个都是痴人。我见过丢了亡妻一支簪子的铁塔似的汉子，在我这儿哭成泪人。你笑痴——那是你的福气。真到了痴那天，你盼着世上多几个痴人。」他把门为你拉开，「慢走。愿你一辈子用不上我这行。」"}}]},{xinglu:"是岁鬼市一课。老人把话说到根上——「我守着一屋子没人要的东西，其实守着一屋子没人讲完的故事。」",text:"「我师父是官府的库吏出身。」老人说，「他传我这行当，传的却不是收东西的法子。」「师父传我的话是：物有主，主有心，心有急缓。」老人说，「收东西的法子三天就会，辨人心的功夫十年难成。丢了药方的人和丢了银子的，急法不一样；丢东西的穷人和丢东西的富人，找法也不一样。这行当的功夫，全在听人说丢东西那几句话里。」「天不早了。」老人点起灯，「我这儿夜里也开门——丢东西的人，是不分时辰的。你慢走，路上小心别落了东西。落了也不要紧——这世上还有我这样的人。」",options:[{label:"「两句话，我记牢了。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"恩",text:"一眼认出包袱上的字迹，省了老人三个月的腿"},text_after:"你帮着把那箱旧信按笔迹归了类——竟分出七户不同的人家。老人眼睛都亮了：「七年了，头一回有人帮我拆这个死结。这七户人家，我挨家去送——送完一户，我就少守一件。」他非要塞给你一枚旧铜钱作谢：「失物账上添你一笔——这行的规矩，帮过忙的，都是祖师爷的人。」"}},{label:"「失物多了，你拾得过来？」",end:!0,effect:{stat:{wuxing:1},text_after:"「吃什么？」老人指指墙角的一张木床、一只小灶，「我就住这儿。失物招领不收钱——我另有营生，替各家修修补补，饿不死。」他嘿嘿一笑，「你问的不是这个吧？你是问我图什么。图什么——图我娘。我娘丢了她的陪嫁镯子，急疯了。有人替她寻回来了。那年我十岁，站在门口看那个人把镯子递给我娘——我娘笑了。我这辈子，就想当那个人。」"}}]}]},adv_g197_wenlu:{id:"adv_g197_wenlu",title:"路遇驼背阿婆——在帮派堂口只问不答",mother:"M7",channel:"T3",rarity:1,entry:{node:"tangkou",chance:.06},stages:[{xinglu:"是岁帮派堂口逢驼背阿婆。驼背阿婆的话糙，理却直——「问题挂在这儿，不急着答——有些问题本身就是灯。」",text:"你路过帮派堂口，驼背阿婆拦住你：「客人，问你个事——你答不上来不要紧。」「我这牌子写着『只问不答』，不是傲。」驼背阿婆解释道，「是我发现——我一给答案，人就不想了。答案是个懒东西，问句才养人。」「你替我想想。」驼背阿婆把一张写着问句的纸条递过来，「这个问题挂了三年没人答。你说说看——答不好也不要紧。」",options:[{label:"「这问题，我试试。」",goto:1,effect:void 0},{label:"「你到底答不答。」",end:!0,effect:{stat:{wuxing:1},text_after:"「无聊？」驼背阿婆哈哈大笑，「你这话说得对——问题是挺无聊的。答案多痛快，一刀见血。可我告诉你，一刀见血的痛快，跟一刀断命的糊涂，是同一个刀法。你嫌我无聊，就是嫌自己想事太慢——慢工出的东西，急工比不了。走吧走吧，等你哪天急不动了，自然会回来找无聊。」"}}]},{xinglu:"是岁帮派堂口一课。驼背阿婆把话说到根上——「人这一生，答案会过期——问题不会。」",text:"「我这儿来过三种人。」驼背阿婆掰着指头，「你猜是哪三种？」「三十年挂着的那个问题是：人这一生，是答案重要，还是问得对重要？」驼背阿婆缓缓道，「年轻时我赌答案是重要的——答对了就赢了。后来发现，答对的都有过期的一天。如今我改赌了：问得对重要。问对了，答错了能重来；问错了，答对了也是白答。」驼背阿婆笑了笑，「你呢？你怎么赌？不用现在答——这个问题，现在也归你了。」驼背阿婆把一张纸条郑重推给你：「这个问题归你了。不急——哪天想通了，丢进我这竹筒里就行，人不用来。问题认字不认人。」",options:[{label:"「有您这样的店，是帮派堂口的福气。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"恩",text:"听驼背阿婆讲哑巴师父的沙地问句，学会「看还是觉得」"},text_after:"你收下那个问题，揣了三年。第三年秋天你在异乡的田埂上想通了——回去时驼背阿婆的店还开着，你把答案丢进竹筒。后来听说他每逢初一就摇竹筒听响，笑着说：「这条又满了。」你不知道他说的哪条是你——可你知道，有个人的问题，替你养了三年的心。"}},{label:"「问题再好，不顶饭吃。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不顶饭吃？」驼背阿婆不急不恼，「饭是吃的，问题是活的。光吃饭不想事的人，跟牲口拉磨一个样——磨转得再快，路一寸没走。我不是笑话你——我五十岁之前也是这么活的。」他拍拍一张折了又折的路引，「后来才明白：问，是人跟牲口隔的那一道。」"}}]}]},adv_g198_jizhang:{id:"adv_g198_jizhang",title:"销金窟的一课：少年替人情记着账",mother:"M8",channel:"T1",rarity:2,entry:{node:"xiaojinku",chance:.09},stages:[{xinglu:"是岁销金窟逢少年。少年的话糙，理却直——「我记的不是债——是这世上「有人还过」的证据。」",text:"你到销金窟时，两个人正拉扯着找少年评理——少年翻开账本，一句话就断了案。「我这账，记的不是钱。」少年敲敲一匣子记着人情往来的木签，「你欠谁一顿饭、谁替你垫过棺材本、你小时候谁背你趟过河——这些，钱还不清，礼还不上，就记在我这儿。记着，人情就还活着。」「你识字吧？」少年把笔递过来，「帮我誊一页。誊账有个讲究——字要端正，心要放平。你试试。」",options:[{label:"「这笔账，我也想记。」",goto:1,effect:void 0},{label:"「旧账就让它过去。」",end:!0,effect:{stat:{wuxing:1},text_after:"「记它做什么？」少年把笔搁下，「你不记，它就不存在了么？不——它在你心里烂着，在他心里烂着，两败俱伤。记出来，才有得还、有得清、有得忘。账不是记仇——是把烂在心里的东西，拿到日头底下晾晾。」"}}]},{xinglu:"是岁销金窟一课。少年把话说到根上——「我这账本不是讨债的——是替人把「该记得」留住。」",text:"「你见过两家人为一笔账断了二十年的来往么？」少年说，「我接手过。」「烧账的事，是大饥那年。」少年说，「富户囤粮抬价，我这账上记着他们家欠下的十七户人情——都是灾年穷人帮过他们先人的。他们怕我这张账掀老底，半夜送来一箱金子，让我把那页烧了。」少年冷冷道，「我把金子退了，账抄了三份：一份我收着，一份藏在庙里，一份连夜送到那十七户人手里。后来饥年过完，那富户的粮，被十七户人凭一页旧账联名告发了。官府问：谁记的账？——没人说。账在，就够了。」「替我记一笔。」少年忽然说，「就说：今天有个过路的客人，坐下来听完了整本账。这一笔记下——你也是账里的人了。」",options:[{label:"「把我记上。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"恩",text:"帮少年誊账一页，字正心平，得了保管员三分真传"},text_after:"你替他跑了一趟，把一册抄本送到了邻县。收账的是个白胡子老者，翻开一看就红了眼：「还有人记着这笔……」你回程时少年已在门口候着——他不要你讲细节，只问了一句：「送到就行了？」你说送到了。他长出一口气：「好。这一笔，两头都活了。」"}},{label:"「记账记成痴，何苦。」",end:!0,effect:{stat:{wuxing:1},text_after:"「销不得。」少年摇头，「死账销了，你就当这人没来过。可他来过——他欠账的时候是个活人，有爹娘、有脾气、有舍不得。销账容易，抹一个人难。」他把死账那册抱在怀里，「我清明念他们名字的时候，庙里老和尚说我痴。我说你不痴不懂——被念到的名字，才算在人间留过脚印。」"}}]}]},adv_g199_shouwu:{id:"adv_g199_shouwu",title:"白发老丈在乱葬义庄守着一件旧物",mother:"M5",channel:"T2",rarity:1,entry:{node:"yizhuang",chance:.1},stages:[{xinglu:"是岁乱葬义庄逢白发老丈。白发老丈的话糙，理却直——「守的东西不值钱——守本身值钱。」",text:"乱葬义庄角上，白发老丈在给半座旧石桥掸灰，一下一下，像在给它梳头。白发老丈守半座旧石桥守出了规矩：什么时辰来看、看哪几处、坏了找谁修——「规矩立下了，人换不要紧，规矩不能换。」白发老丈递过来一块抹布：「搭把手？擦一擦你就懂了——懂了的人，往后走到哪儿都见不得东西受委屈。」",options:[{label:"坐下陪白发老丈说说话",goto:1,effect:void 0},{label:"「破烂一个，守它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「赶路要紧，是正经话。」白发老丈点头，「可我告诉你——路走完了，能想起来的，往往不是路上多快，是谁让你停了一脚。你走吧，我不拦。」你走出半里地，脚步不自觉慢了下来。"}}]},{xinglu:"是岁乱葬义庄一课。白发老丈把话说到根上——「物不会说话，可物记得每一个守过它的人。」",text:"「最难的不是守，是没人懂。」白发老丈笑笑，「懂的人不来，来的人不懂——守着守着就只剩你一个人了。」「那年水退了，半座旧石桥还在，人也都在。」白发老丈说，「从那以后我就明白了——你守着它，它就替你守着这一片的人心。」白发老丈站起身，最后擦了一遍半座旧石桥：「天不早了。守物人的话就这么多——你要记，就记一句：物在人守。人要是都不守了，物就真没了。」",options:[{label:"「这话我记一辈子。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"恩",text:"帮白发老丈修缮半座旧石桥，乱葬义庄的旧物得以长存"},text_after:"你陪白发老丈坐到日头偏西。临走他说：「今天这一坐，比擦十年灰有用。」你问为什么。他说：「东西怕的不是旧，是没人坐。有人肯坐，它就还是个去处。」"}},{label:"「您自己守着就好。」",end:!0,effect:{stat:{wuxing:1},text_after:"白发老丈也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g200_chuanyi:{id:"adv_g200_chuanyi",title:"路遇盲眼老者——在酒旗长街把手艺往下传",mother:"M3",channel:"T3",rarity:2,entry:{node:"yh_changjie",chance:.08},stages:[{xinglu:"是岁酒旗长街逢盲眼老者。盲眼老者的话糙，理却直——「我这一双手是从师父手上接来的，得接着往下递。」",text:"酒旗长街里，盲眼老者正带着徒弟做活，手里是一把用了半辈子的凿子，一招一式都极稳。「外行看手艺，看的是巧。」盲眼老者说，「内行看的是匀——匀了才稳，稳了才久。做人一个理。」「你要是感兴趣，我讲细点。」盲眼老者说，「讲了你就懂——懂了的人，走到哪儿都替这门手艺说句话。」",options:[{label:"「为什么是这个形？」",goto:1,effect:void 0},{label:"「手艺而已，不值一提。」",end:!0,effect:{stat:{wuxing:1},text_after:"「问挣钱？」盲眼老者放下一把用了半辈子的凿子，「问这话的，十个里十个学不成。挣钱的手艺满街都是，可饿不死人的行当里，站得住的从来不是钱——是牌子。牌子怎么来的？活做人正。你要只为钱，趁早干别的，别糟蹋这行。」你脸上挂不住，可他说的你没法反驳。"}}]},{xinglu:"是岁酒旗长街一课。盲眼老者把话说到根上——「教会徒弟饿死师父——说这话的人，手艺本来就不到家。」",text:"「我师父当年教我，可比现在狠多了。」盲眼老者笑着摇头。「我那桩险事是这样的：」盲眼老者道，「一把用了半辈子的凿子借给人用了三天，回来就不好使了。我查出问题，修了三天。从那以后我的规矩是：家伙什可以借，规矩不能借——借出去之前，先教会人家怎么用。后来我索性连人带艺一起教——教会了，就不怕借了。」「我这一把用了半辈子的凿子，早晚传给肯下苦功的人。」盲眼老者望着作坊，「也许是我徒弟，也许是徒弟的徒弟，也许——是个今天来歇脚的路人。缘分这东西说不准。」",options:[{label:"「我若有徒，也这么教。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"义",text:"在酒旗长街亲手学做盲眼老者的活，得「敢露怯」之教"},text_after:"你上了手，做得歪歪扭扭。盲眼老者在旁边看着，不催不笑，等你做完才说：「歪归歪，下手不虚——你是块料，就是没人给你上过头一课。」你问什么头一课。他说：「敢在自己人面前做坏。多少有天分的人，就毁在不敢露怯上。」这句话你记了很多年。"}},{label:"「与我何干，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「道理是会讲。」盲眼老者不恼，「可我讲了三十年，徒弟们信了——你嘴上不信，眼睛信了。你进来到现在，眼睛没离开过它三回。」你哑口无言。他笑着送你出门：「不信没关系，手艺等得起。它等你一辈子，我都等得起。」"}}]}]},adv_g201_haiyuan:{id:"adv_g201_haiyuan",title:"路遇老人——在驿站替故人还愿",mother:"M4",channel:"T1",rarity:1,entry:{node:"yh_yizhan",chance:.13},stages:[{xinglu:"是岁驿站逢老人。老人的话糙，理却直——「人走了，愿不能跟着走——愿得有人替他走完。」",text:"老人把一份没还清的人情护在怀里避雨——护得比自己的性命还紧。「他说过，这事办成了，他就了无遗憾。」老人望着一份没还清的人情，「他走了两年，我走了两万里的路。你说值不值？我不算这个账——我只知道，他临终看我的那一眼，我一辈子忘不掉。」「帮我看看这字还认得出么？」老人展开一页旧纸，「水渍沤了一角——这可是他的亲笔，少一个字，愿就缺一角。」",options:[{label:"「帮您辨认这页纸。」",goto:1,effect:void 0},{label:"「路远事烦，别找了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「留着何用？」老人把一份没还清的人情举起来给你看，「你看它像东西吗？不像了——它是一句没说完的话。话没了，人才真的没了。」他说完自己收好，朝你拱拱手，「客人，话糙了。可这理，你早晚用得上。」"}}]},{xinglu:"是岁驿站一课。老人把话说到根上——「故人把愿留给我，是拿我当自己人——这份信，比愿本身重。」",text:"老人沉默了一阵，说：「其实这个愿，我本可以早点还的。」「讲一个还愿的故事：有个老猎户，临终托我把他攒的一袋盐分给当年一起守山的弟兄。」老人说，「弟兄散了，我找了四年，七个找到了六个。第七个，去年在狱里寻着——他犯了事。我把盐给他，他捧着哭了半宿，说：哥几个还记着我。出狱那天，他来找我，如今在山上替人守林。你说，一袋盐值什么？可有些时候，一袋盐就是把人从沟里拉上来的绳。」老人重新收拾好行囊：「客人的话我记下了。愿还得接着赶路——它等不起，我也不能老。」他冲你拱手，「你若哪天也遇上该还的愿——别拖。拖，是还愿这行唯一的死敌。」",options:[{label:"「我记住了。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"恩",text:"捎老人一程，听了一个还愿人的故事"},text_after:"你把记得的线索全说了——竟真有一条有用。老人愣在原地，半晌，深深作了个揖：「客人，你今天替一个走了两年的人，把愿往前推了三里地。」他非要留给你一样谢礼，你说不必，他坚持：「愿上的账，不能欠。你收下——不然我这一路，就白背了心债。」"}},{label:"「愿是虚的，人死了就完了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「帮不上不打紧。」老人摆摆手，「别缠着我——这话就伤人了。我讨的不是你的帮，是你让一步路。让一步路，天塌不下来。」他让到道旁，先请你走。你从他身边过的时候，忽然觉得这一步，让得自己心里发虚。"}}]}]},adv_g202_zengxing:{id:"adv_g202_zengxing",title:"平安号镖局分号的一课：婆婆白送路上的东西",mother:"M1",channel:"T2",rarity:3,entry:{node:"yh_biaoju",chance:.07},stages:[{xinglu:"是岁平安号镖局分号逢婆婆。婆婆的话糙，理却直——「路边这点东西救不了命——可有时人就差这一口。」",text:"你打平安号镖局分号过，婆婆招呼你：「歇歇脚？不要钱，也别推——推就见外了。」「有人问我图什么。」婆婆摆摆手，「图什么？我夜里从这儿过，看见路人的灯笼从我摆的东西旁边过去——那一刻我就图了。人活着，总得有点自己知道就行的事。」婆婆把东西塞到你手里：「拿着。别谢——要谢，往后你也给别人备一份。」",options:[{label:"「我来记这一笔。」",goto:1,effect:void 0},{label:"「白拿的东西，来路不正。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不占便宜是好品性。」婆婆点头，「可我这不叫便宜——叫过路钱。你今天不喝我这口，往后你发达了在别处摆摊，让人白喝——这账就平了。」他硬塞给你，「路上没有白拿，只有先拿后还。你先欠着，我说这话不臊——你将来还得起。」"}}]},{xinglu:"是岁平安号镖局分号一课。婆婆把话说到根上——「赠出去的东西不折本——折的是心，攒的也是心。」",text:"「我这一篮挂在枝头的果子，起头不是给人用的。」婆婆声音低了，「是我给自己备的。」「那年来了个贼，夜里偷我的东西不说，还砸了我的牌子。」婆婆说，「我第二天照样摆，牌子重写一块，添了四个字：『夜路慢行』。后来那贼又来——这回是白天，红着脸放下一捆柴，一句话没说走了。」婆婆呵呵地笑，「你瞧，善这东西不咬人，它泡人。泡久了，铁石心肠也软。」婆婆给你包了一份路上用的：「拿着。我别的不送——就送个『路上有人惦记』的踏实。你揣着它走夜路，脚底下稳当。」",options:[{label:"「这摊子会一直在的。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"义",text:"受婆婆所托，允诺传递路边的规矩"},text_after:"「我可没说一定是我。」你摆手。婆婆笑道：「兴许不是。可你今天多站了这半晌——比别人近了一步。这摊子挑人，跟守物挑人一样：挑肯停脚的。」你走出几里地回头望，他还坐在一篮挂在枝头的果子边——像路长出来的一部分。"}},{label:"「世道就这样，你改变不了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」婆婆居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一篮挂在枝头的果子像一方小小的印，盖在漫长的路上。"}}]}]},adv_g203_shouye:{id:"adv_g203_shouye",title:"路遇中年汉子——在城隍庙夜里替人醒着",mother:"M2",channel:"T3",rarity:1,entry:{node:"yh_chenghuang",chance:.06},stages:[{xinglu:"是岁城隍庙逢中年汉子。中年汉子的话糙，理却直——「白天人挤人，夜里心贴心——夜里肯应你一声的，都是家里人。」",text:"城隍庙的夜里只有中年汉子醒着——他给你指了宿处，又提着一仓新入的粮食巡回去了。「夜里赶路的，十个里有三个心里揣着事。」中年汉子给你照着亮，「我不问你什么事——我就把你送到亮处。人到了亮处，事就小了一半。」「往前头去有段黑路。」中年汉子把灯举高了些，「我送你过——反正我也要巡到那边。」",options:[{label:"「夜里的事，讲讲。」",goto:1,effect:void 0},{label:"「我家的事不用你管。」",end:!0,effect:{stat:{wuxing:1},text_after:"「认得黑路是好事。」中年汉子没拦你，「可你认得的是路——路认不认你，两说。去年有个自认得路的，掉进了拆了半截的桥坑里，躺了一夜——他不知道那坑，我知道。」他举灯照了照那个方向，「喏，就那儿。坑还在，天亮我得上报。」你没再犟，跟着他走了那条亮路。"}}]},{xinglu:"是岁城隍庙一课。中年汉子把话说到根上——「守夜不图别的——图鸡叫的时候，家家还都是囫囵的。」",text:"「我师父传我一仓新入的粮食的时候说过一句话。」中年汉子说，「我用了二十年才听懂。」「师父那句话是：守夜守的不是夜，是人心里那点亮。」中年汉子摩挲着一仓新入的粮食，「我用了二十年才懂——灯灭了可以再点，人心里的灯灭了，夜里就真黑了。所以我巡夜从不偷懒：我的脚步声，就是几百户人心里那盏灯的灯芯响。」「天快亮了。」中年汉子打了个梆，「五更，天下太平。你听——鸡都叫了。这就是守夜人的一天：什么都没发生，就是最大的事。」",options:[{label:"「保我十年太平。」",end:!0,effect:{stat:{wuxing:2},trait:{yi:1},ledger:{type:"义",text:"受中年汉子夜路相送一程，城隍庙三里无事故"},text_after:"灯熄了，天亮了。你走出城隍庙很远，回头看不见灯，可你知道它在——就像你知道这世上有一群人，一辈子活在别人的梦里，为的是别人的梦别变成噩梦。你朝着城隍庙的方向作了个揖。天光大亮，路上人多了，谁也不知道你这一揖揖的是什么。"}},{label:"「夜里太平是运气，不是你的功。」",end:!0,effect:{stat:{wuxing:1},text_after:"「我照不了多远，是真的。」中年汉子看着手里的灯，居然认了，「可我熄了，还有下一盏——我挑的徒弟，正学着觉浅呢。灯照不了多远不要紧，要紧的是一直亮着。你要赶路就赶吧——」他让开道，「前头三里没灯。你走的时候，替我记着这三里的黑。哪天你点上什么，别忘了我这话。」"}}]}]},adv_g204_shiyi:{id:"adv_g204_shiyi",title:"清瘦老者在车马行替失物寻主人",mother:"M6",channel:"T1",rarity:1,entry:{node:"yh_chemahang",chance:.13},stages:[{xinglu:"是岁车马行逢清瘦老者。清瘦老者的话糙，理却直——「我这一行没有大买卖——都是小东西，可小东西连着大心事。」",text:"车马行里，清瘦老者守着一屋一箱无人认领的旧信，见你进来，先问一句：「客人丢过什么？」「有人笑我守着一堆破烂。」清瘦老者不恼，「我说你不懂——破烂搁在你家是破烂，搁在我这儿，是有主的。只等它的主人哪天想起来。人这一辈子，谁没落下过点什么？」「你说，」清瘦老者忽然问，「东西找到主人重要，还是主人放下了重要？我想了十年，没想明白。」",options:[{label:"「我帮你认认。」",goto:1,effect:void 0},{label:"「谁丢了东西自己不会找。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不会找？」清瘦老者叹口气，「客人，会找的人，丢的都是值钱东西。不会找的——老人丢了，孩子丢了，痴了的人丢了。他们自己找不了，家里人找疯了。我这行拾的，一半是物，一半是人。」他说完不再看你。你走出去几步，觉得方才那句话，轻佻得不像自己的。"}}]},{xinglu:"是岁车马行一课。清瘦老者把话说到根上——「遗落的东西不会说话——可它们都在等人。」",text:"「我这行有个祖师爷。」清瘦老者笑了，「说出来你都不信——是个邮差。」「那件一文不值的，是半只风筝。」清瘦老者从柜里捧出来，「碎得没法再飞了。是个娃丢的——他爹重病，他放了一天风筝，说放完了爹就好了。爹没好，走了。风筝也丢了。」清瘦老者声音低下去，「我找了他四年。找到时那娃已经不哭了，只说了句：叔叔，风筝回来了，是不是爹也记得回来？我答不上来。我把风筝给他，他把他爹留的一枚旧扣子给我——说换。我没推。我库里的东西，就数这件最贵。」清瘦老者送你到门口，回身望着满屋一箱无人认领的旧信：「客人，你笑我守破烂也好，敬我守念想也好——这屋子东西，早晚会一件一件回到人手里。到那时候，我这屋子空了，我这心，也就满了。」",options:[{label:"「两句话，我记牢了。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"恩",text:"听清瘦老者讲半只风筝的旧事，识得失物的轻重"},text_after:"你认出了包袱上的字——是北边某府的馆阁体，还带着军中的写法。「军中的！」清瘦老者一拍大腿，「怪不得我在商旅里问不出——我往驿站问去！」他高兴得像捡了宝，拉着你的手直摇：「客人，你这一眼，顶我三个月的腿。」"}},{label:"「东西丢了再买就是。」",end:!0,effect:{stat:{wuxing:1},text_after:"「拾不过来。」清瘦老者坦白得很，「天下的失物，我一辈子拾不完。可我多拾一件，世上就少一件没着落的。你这话跟师父当年说的一模一样——他后来呢？他拾了一辈子。」他拿起册子，「拾不过来，就一件一件来。日子长着呢。」"}}]}]},adv_g205_wenlu:{id:"adv_g205_wenlu",title:"在雁回峡，只问不答的独臂客",mother:"M7",channel:"T2",rarity:1,entry:{node:"yh_xia",chance:.07},stages:[{xinglu:"是岁雁回峡逢独臂客。独臂客的话糙，理却直——「人这一生，答案会过期——问题不会。」",text:"独臂客正把新写的问题挂上一册写满问句的手记：「客人看看，这个问题值得挂么？」「我这牌子写着『只问不答』，不是傲。」独臂客解释道，「是我发现——我一给答案，人就不想了。答案是个懒东西，问句才养人。」「你替我想想。」独臂客把一张写着问句的纸条递过来，「这个问题挂了三年没人答。你说说看——答不好也不要紧。」",options:[{label:"「我是在奔着一条路。」",goto:1,effect:void 0},{label:"「怪人一个，不理也罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「无聊？」独臂客哈哈大笑，「你这话说得对——问题是挺无聊的。答案多痛快，一刀见血。可我告诉你，一刀见血的痛快，跟一刀断命的糊涂，是同一个刀法。你嫌我无聊，就是嫌自己想事太慢——慢工出的东西，急工比不了。走吧走吧，等你哪天急不动了，自然会回来找无聊。」"}}]},{xinglu:"是岁雁回峡一课。独臂客把话说到根上——「我问了一辈子——问出来的东西，比读出来的多。」",text:"「问了一辈子，也栽过跟头。」独臂客说，「讲一件——讲完你就知道，问题也能伤人。」「三十年挂着的那个问题是：人这一生，是答案重要，还是问得对重要？」独臂客缓缓道，「年轻时我赌答案是重要的——答对了就赢了。后来发现，答对的都有过期的一天。如今我改赌了：问得对重要。问对了，答错了能重来；问错了，答对了也是白答。」独臂客笑了笑，「你呢？你怎么赌？不用现在答——这个问题，现在也归你了。」「我这一册写满问句的手记上的问题，谁都可以摘。」独臂客说，「摘走的记得回来还——还的不是纸条，是你自己酿的答案。利息不高，一辈子还一回就行。」",options:[{label:"「利息我必还。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"受独臂客所托带走一个三十年的问题"},text_after:"「看，还是觉得——这一句你带走了。」独臂客满意地送你出门。后来你在生意上、恩怨里、抉择前，无数次问自己这一句。它不能替你做对的事——可它让你少做了许多自以为对的事。你从此逢人便传这句话，传的时候都说是从一个怪老头那儿听来的。"}},{label:"「我从不问路，只看脚下的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「从不问路？」独臂客看着你，忽然认真了，「客人，我不拦你。可我送你一句话：不问路的人，不是路盲——是路盲里胆子最大的。老天爷不在乎你问不问，它只管把你引到岔路口。你凭本事闯，闯对了是命大，闯错了——」他顿了顿，「没有人给你收尸。走吧。这话搁这儿，你哪天想起，算我的。」"}}]}]},adv_g206_jizhang:{id:"adv_g206_jizhang",title:"水门码头里替人情记着账的独臂客",mother:"M8",channel:"T3",rarity:1,entry:{node:"lj_shuimen",chance:.07},stages:[{xinglu:"是岁水门码头逢独臂客。独臂客的话糙，理却直——「记账人手上要清，心上要热——光清不热，是阎王；光热不清，是糊涂虫。」",text:"独臂客见你生面孔，先递茶再开口：「客人路过的吧？有没有账，都坐坐——我这儿不只是记账的。」「我这行最要紧的是一碗水端平。」独臂客说，「欠账的是恩人——没有他欠着，就没有还的那一天；还账的也是恩人——他来还，情分才续上。我两头都敬。」「你识字吧？」独臂客把笔递过来，「帮我誊一页。誊账有个讲究——字要端正，心要放平。你试试。」",options:[{label:"「头一页，讲讲。」",goto:1,effect:void 0},{label:"「人情账，记它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「过去？」独臂客摇头，「过得去的才叫过去。过不去的，你不理它，它就长在心里长成疙瘩。我这柜子里的账，一半是让人过得去的——账面摆出来，多少年的疙瘩，一句话就解了。」"}}]},{xinglu:"是岁水门码头一课。独臂客把话说到根上——「死账不销——销了，欠的人和被欠的人，心里都空一块。」",text:"「记账人也有难处。」独臂客说，「最难的一回，差一点把这柜账烧了。」「这页上没几个钱。」独臂客指着那页字，「记的是：某年大疫，西街王家把最后一副药让给了东街李家，自己没熬过去。李家记下这笔，三代人来还——还不到王家坟上，就还到王家剩下的老闺女身上：出嫁陪的嫁妆、逢年送的米、老了以后请的郎中。」独臂客合上册子，「一副药换三代人的情。你说我这一柜子账，值多少钱？」独臂客把茶续满：「别急着走。听账人的道理，不在账上——在你听完以后，回头看你自家那本账。人人心里都有一本，只是没人替你誊清。」",options:[{label:"「回头我看自家那本账。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"听独臂客讲大饥年保账的旧事，识得一页纸的分量"},text_after:"「当得起什么。」独臂客连连摆手，「我这行，说到底是替人管着念想。念想是他们的，我只是个保管员。」可你看得出来，他说这话时腰板挺得笔直——一个一辈子被几千户人信着的人，那份挺直，是拿三十年的笔一笔一笔撑起来的。"}},{label:"「人情最靠不住，你记了也白记。」",end:!0,effect:{stat:{wuxing:1},text_after:"「白记？」独臂客居然点头，「你说得对——十笔情账，有三笔是白记的。可剩下七笔呢？」他翻开册子给我看密密麻麻的还账记录，「人情是靠不住——可总得有人头一个信。我信了三十年，换回这七本册子的『还』字。你赌人不靠得住，你赌输了也就输了；我赌人靠得住，我赢得一街的太平。这笔账，你自己算。」"}}]}]},adv_g207_shouwu:{id:"adv_g207_shouwu",title:"漕帮总舵来了个守着一件旧物的老人",mother:"M5",channel:"T1",rarity:2,entry:{node:"lj_caobang",chance:.09},stages:[{xinglu:"是岁漕帮总舵逢老人。老人的话糙，理却直——「我不守物——我守的是「还有人记得」这四个字。」",text:"老人在漕帮总舵守了半座旧石桥，见你打量，先开口说了它的来历。老人给你看半座旧石桥上的旧痕：「每一道痕都有来历。守物人得认得它全部的伤——认得了，才轮得到你守。」老人递过来一块抹布：「搭把手？擦一擦你就懂了——懂了的人，往后走到哪儿都见不得东西受委屈。」",options:[{label:"「它有故事，我愿听。」",goto:1,effect:void 0},{label:"扫一眼就走",end:!0,effect:{stat:{wuxing:1},text_after:"老人没追出来。你走了几里地，越想越不对——人家守了几十年的东西，你一句「破烂」就打发了。回头补一句的时候，老人正围着半座旧石桥忙，见了你也不提方才的事，只说：「回来了？搭把手。」你愣是没说出道歉的话——他已经把它翻篇了。"}}]},{xinglu:"是岁漕帮总舵一课。老人把话说到根上——「物不会说话，可物记得每一个守过它的人。」",text:"「守物人最怕什么，你知道么？」老人问你，没等你答，「最怕自己也觉得它没用了。」「动摇过的那回，是它塌了一角。」老人说，「我哭了半宿，第二天开始学着修。守物人都是这么过来的——先是舍不得，再是学不会，最后学会了。」老人朝半座旧石桥作了个揖，转身又朝你作了个揖：「一个替它，一个替它谢你。往后不管你走多远——记得这世上还有人在守着点什么东西，你心里就有底。」",options:[{label:"「这话我记一辈子。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"义",text:"与老人共守半座旧石桥一夜，学会守物的规矩"},text_after:"你帮着擦完了。手上的灰蹭了一袖子，心里却出奇地熨帖。老人看着擦亮的半座旧石桥，半天说了句：「行了，今天这一遍，值。」你走出很远才咂摸出味儿来——他谢的不是你，是它今天又被人认真对待了一回。"}},{label:"「往后再说吧。」",end:!0,effect:{stat:{wuxing:1},text_after:"老人也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g208_chuanyi:{id:"adv_g208_chuanyi",title:"老汉在书院把手艺往下传",mother:"M3",channel:"T2",rarity:3,entry:{node:"lj_shuyuan",chance:.08},stages:[{xinglu:"是岁书院逢老汉。老汉的话糙，理却直——「徒弟学不学得会看天分，教不教得会看良心。」",text:"书院里最齐整的就是一杆磨得发亮的老秤——老汉说，家伙什齐整，手艺才齐整。「外行看手艺，看的是巧。」老汉说，「内行看的是匀——匀了才稳，稳了才久。做人一个理。」「你要是感兴趣，我讲细点。」老汉说，「讲了你就懂——懂了的人，走到哪儿都替这门手艺说句话。」",options:[{label:"「说实话——这是真功夫。」",goto:1,effect:void 0},{label:"「这些老规矩，过时了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「问挣钱？」老汉放下一杆磨得发亮的老秤，「问这话的，十个里十个学不成。挣钱的手艺满街都是，可饿不死人的行当里，站得住的从来不是钱——是牌子。牌子怎么来的？活做人正。你要只为钱，趁早干别的，别糟蹋这行。」你脸上挂不住，可他说的你没法反驳。"}}]},{xinglu:"是岁书院一课。老汉把话说到根上——「手上的功夫十年教得会，手上的分寸三十年说不清。」",text:"「我这一杆磨得发亮的老秤差点断在一桩事上。」老汉摩挲着它，「你听听——听完你就明白手艺人为什么较真。」「那个走了样的徒弟，拿这门手艺坑人。」老汉声音沉下来，「我上门去，当着人面把一杆磨得发亮的老秤从他手里要走回来——手艺是从这上头学的，现在从这上头收回来。他哭，我也难受。可规矩就是规矩：艺不正，师收之。」「我这一杆磨得发亮的老秤，早晚传给肯下苦功的人。」老汉望着作坊，「也许是我徒弟，也许是徒弟的徒弟，也许——是个今天来歇脚的路人。缘分这东西说不准。」",options:[{label:"「您的手艺，不会断。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"恩",text:"看老汉带徒一下午，学会「骂是疼」的道理"},text_after:"「实话说得好听。」老汉满意地笑了，「就冲你这句实话，我把关子揭了——这一杆磨得发亮的老秤是这个形，是因为它得让用的人先低头。你低头了，心就沉了；心沉了，活就稳了。器物教人，比人教人快。」"}},{label:"「道理谁都会讲。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要钱？」老汉愣了一下，随即大笑，「我今天一个字没收你钱，还搭了一下午的茶——你要是听成了要钱，那我这一下午白讲了，你的耳朵也白带了。走吧走吧——」他摆摆手，笑骂道，「亏你今天还看了我半天活。看活不看人，你差得远呢。」"}}]}]},adv_g209_haiyuan:{id:"adv_g209_haiyuan",title:"城外湖泽的一课：驼背阿婆替故人还愿",mother:"M4",channel:"T3",rarity:1,entry:{node:"lj_huze",chance:.06},stages:[{xinglu:"是岁城外湖泽逢驼背阿婆。驼背阿婆的话糙，理却直——「故人把愿留给我，是拿我当自己人——这份信，比愿本身重。」",text:"驼背阿婆在城外湖泽打听路，手里攥着一封没寄出去的信——他在替谁了却一桩心愿。「这愿许了三年了。」驼背阿婆摩挲着一封没寄出去的信，「走一段，问一段。有人笑我：人都没了，还折腾什么？我说——就是人都没了，才要折腾。活着的人可以等你，走了的人，等不了。」驼背阿婆看着你：「你说，人走了以后，到底知不知道我们还在替他办事？」不等答，他自己接了：「知不知道都要办——这是我的事，不是他的事。」",options:[{label:"「这字我还认得。」",goto:1,effect:void 0},{label:"「路远事烦，别找了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「与我无关？」驼背阿婆也不恼，「是啊，天下事都与谁无关呢？他跟我无关的时候，我欠了他一辈子。你走吧——愿你一辈子都用不上替人还愿。用不上，是福气。」"}}]},{xinglu:"是岁城外湖泽一课。驼背阿婆把话说到根上——「替死人办事，得比替活人办事更上心——死人不会催你，也不会谢你。」",text:"「我老婆子生前总念叨，」驼背阿婆声音软下来，「这个愿，是为她还的。」「为我老婆子还的愿，办起来最不觉得累。」驼背阿婆摩挲着一封没寄出去的信，「有人说我傻，人都没了。我说你没懂——她还哪儿都没去。她在这个愿里。我每走一里路，她就跟我走一里。等愿还完，她也就到家了。」驼背阿婆说这话时眼里有泪，脸上却在笑。「我走了。」驼背阿婆背起行囊，「这愿还完，我就回家种地——把替人还愿的道理，讲给村口的娃娃们听。让他们知道：这世上有一种债，还的是心安。」",options:[{label:"「这碗水，我记着。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"义",text:"受驼背阿婆所托记下善缘，替走了的人结一个活缘"},text_after:"你帮着辨出了那页纸上的字——缺的那一角，是收信人的名字。驼背阿婆盯着那个名字看了许久：「对上了。就差这个字，我在县里翻了三天的户籍。」他抬头时眼眶红了，「客人，你今天不是帮我看字——你是替他把最后一句话，送到了门口。」"}},{label:"「愿是虚的，人死了就完了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「完了就完了？」驼背阿婆站定，认真看你，「人走茶凉是世道。可我把茶端热的这些年，凉不了——你信不信？你今天说这话，是因为还没遇着走的人。遇着了，你会想起我。」他走了，那句话你揣了一路，越揣越沉。"}}]}]},adv_g210_zengxing:{id:"adv_g210_zengxing",title:"驼背阿婆在青羊观白送路上的东西",mother:"M1",channel:"T1",rarity:1,entry:{node:"lj_qingyang",chance:.09},stages:[{xinglu:"是岁青羊观逢驼背阿婆。驼背阿婆的话糙，理却直——「赠出去的东西不折本——折的是心，攒的也是心。」",text:"青羊观的路边，驼背阿婆摆着一串挂在树上的旧草鞋，来者不问，取者不问。「起头也有人笑我傻。」驼背阿婆靠着一串挂在树上的旧草鞋坐下，「白摆着，让人白拿。我说你看着——一个月后你再笑。一个月后，笑我的人绕路也来喝一口。」「客人腿脚快，是赶远路的？」驼背阿婆问完不等答，已经把东西包好了，「远路更要带——不是干粮，是个念想。」",options:[{label:"「往后还走。」",goto:1,effect:void 0},{label:"「天下哪有白给的好事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不占便宜是好品性。」驼背阿婆点头，「可我这不叫便宜——叫过路钱。你今天不喝我这口，往后你发达了在别处摆摊，让人白喝——这账就平了。」他硬塞给你，「路上没有白拿，只有先拿后还。你先欠着，我说这话不臊——你将来还得起。」"}}]},{xinglu:"是岁青羊观一课。驼背阿婆把话说到根上——「白给的东西要正大光明地白给——藏着掖着，善就变了味。」",text:"「我这一串挂在树上的旧草鞋，起头不是给人用的。」驼背阿婆声音低了，「是我给自己备的。」「那年来了个贼，夜里偷我的东西不说，还砸了我的牌子。」驼背阿婆说，「我第二天照样摆，牌子重写一块，添了四个字：『夜路慢行』。后来那贼又来——这回是白天，红着脸放下一捆柴，一句话没说走了。」驼背阿婆呵呵地笑，「你瞧，善这东西不咬人，它泡人。泡久了，铁石心肠也软。」「记住这条道的规矩。」驼背阿婆指指一串挂在树上的旧草鞋，「用的时候想着点别人，够用的就别多拿——这不是我的规矩，是路自己的规矩。守住了，这东西就一直有。」",options:[{label:"「您这样的人，多几个才好。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"义",text:"受驼背阿婆所托，允诺传递路边的规矩"},text_after:"「我可没说一定是我。」你摆手。驼背阿婆笑道：「兴许不是。可你今天多站了这半晌——比别人近了一步。这摊子挑人，跟守物挑人一样：挑肯停脚的。」你走出几里地回头望，他还坐在一串挂在树上的旧草鞋边——像路长出来的一部分。"}},{label:"「你的账你自己算，别算上我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不算上你。」驼背阿婆点头，「我的账是我的。可你走在这条道上，喝过路边的井水、走过别人修的桥、睡过别人盖的亭子——这些账都跟我一样，没人跟你要过。」他拍拍一串挂在树上的旧草鞋，「不用你算我的账。哪天你想起这世道不全是黑的，就够了。」"}}]}]}};Object.assign(e,t);export{t as ADVENTURES17};
